// Update Center: a lightweight "What's New" changelog panel for the hub.
(function () {
  const STORAGE_KEY = "mimiUpdatesSeenAt";

  const CHANGELOG = [
    {
      date: "2026-09-02",
      entries: [
        { emoji: "\u{1F3AC}", time: "00:02", title: "Frame rate limit in Settings \u2014 30, 60, 120 or unlimited", desc: "Caps how often the three 3D games redraw. Unlimited is the default and adds no cap of ours, which means your screen\u2019s refresh rate is the ceiling \u2014 worth being straight about, since drawing faster than your monitor can show just heats the machine up for frames nobody sees. A cap earns its keep in the other direction: holding a heavy game to 30 keeps a laptop cool and quiet, and a steady 30 feels better than an unstable 45. Never applied in VR, where the headset owns its own timing and dropped frames make people ill. One detail worth mentioning: the obvious way to write a limiter \u2014 \u2018has enough time passed since the last frame?\u2019 \u2014 can only ever produce whole divisions of your refresh rate, so asking for 60 on a 144 Hz screen actually gives you 48. This one carries the deadline forward instead and measures 61." },
        { emoji: "\u{1F680}", time: "00:01", title: "The desktop app was rendering everything without the graphics card", desc: "The Windows/Mac/Linux app had hardware acceleration switched off. That was added to work around a graphics driver fault on the machine this project is built on, back when the app was described in its own code as doing \u201cno 3D graphics\u201d \u2014 which stopped being true the moment Kart Circuit, Block Realm and Rival Arena existed. All three are 3D, and without the graphics card they were being drawn by the processor instead, which is on the order of a hundred times slower. That is almost certainly why things felt heavy in the app. It now uses the graphics card, and stops asking Chrome to skip cards it has arbitrarily blocklisted. If the graphics driver genuinely does fall over, the app restarts itself once without acceleration and remembers, so a bad driver means slow rather than broken." },
        { emoji: "\u{1F39B}\uFE0F", time: "00:00", title: "Graphics quality setting", desc: "Balanced, High or Ultra, in Settings. It sets the render resolution and how far you can see in the three 3D games \u2014 the two things that actually move the frame rate. They each used to hard-code this for the weakest machine anyone might use, which left a good PC rendering at half the pixels it could and gave a slower laptop no way to turn anything down. Ultra doubles the resolution cap and pushes Block Realm\u2019s draw distance out; Balanced does the opposite. Reopen a game after changing it." },
      ],
    },
    {
      date: "2026-09-01",
      entries: [
        { emoji: "\u{1F4E5}", time: "00:07", title: "Download App now gives you the current version", desc: "The download menu had been pointing at a release from several versions back, so anyone installing the app got a build without any of this. All six downloads now point at the latest release. Windows is a single .exe you just run \u2014 no install, and if you put it on a D: or E: drive or a USB stick it keeps everything it saves in a folder beside itself rather than on your C: drive. A .zip is on the release page too if you\u2019d rather extract a folder. The Android, TV and Quest apps wrap the website, so they update themselves and only need downloading for a first install." },
        { emoji: "\u26A1", time: "00:06", title: "Fixed: the hub was lagging badly", desc: "The animated background was costing about half the frame rate, and most of that turned out not to be the blocks at all \u2014 the top bar and the dock were using a frosted-glass blur, and because they sit over a canvas that repaints constantly, the browser had to recompute that blur every single frame. They are simply opaque now, which looks the same behind a 97%-opaque panel and is free. The blocks themselves also got cheaper: half of every cube\u2019s faces point away from you and were being drawn only to be painted over, so those are skipped, along with the outline pass, at half the pixel density and half the frame rate. Measured on the shelf: 39 fps before, 60 after, with the same scene. There is now also an \u201cAnimated background\u201d switch in Settings if you\u2019d rather not have it at all, and it bows out on its own if it ever detects it is dragging the page down." },
        { emoji: "\u{1F4C8}", time: "00:05", title: "An FPS counter you can turn on in Settings", desc: "A small live frame-rate readout in the corner, off by default. It follows you everywhere \u2014 the start screen, the game shelf, inside any game \u2014 and colours itself green, amber or red so you can tell at a glance. Click it to reset the lowest reading it has seen, which is the number that actually matters when something stutters." },
        { emoji: "\u{1F30D}", time: "00:04", title: "Rival Arena: online and wireless play", desc: "Play with other people, on the same relay the kart racer already uses. Regional or Global puts you in with whoever else is searching; Host a room gives you a four-letter code to share with someone on your network, and Join takes one. Everyone you\u2019re connected to appears in the arena and can be shot. Tested with real clients on both paths: two players in a shared room, and two more matched into the same global lobby with a shared countdown." },
        { emoji: "\u{1F916}", time: "00:03", title: "Rival Arena: the bots fight each other now", desc: "They used to all target you and nobody else, which made the arena feel like a firing squad pointed one way. Each bot now picks the nearest enemy it can actually see \u2014 which is often another bot \u2014 and re-picks as targets die. Fights break out across the map, and you can round a corner onto two bots already shooting at each other. Their kills show in the feed but don\u2019t count against you." },
        { emoji: "\u{1F3AF}", time: "00:02", title: "Rival Arena: auto-shoot, aim toggles, fullscreen and a bigger view", desc: "Auto-shoot fires for you the moment an enemy is genuinely under the crosshair \u2014 on by default on touch, where holding a fire button while dragging to aim is the awkward part, and off elsewhere. Both it and aim assist can be switched off in the lobby. The arena now fills most of the window instead of sitting in a small box, and there\u2019s a fullscreen button in the corner." },
        { emoji: "\u{1F5B1}\uFE0F", time: "00:00", title: "Fixed: the controller pointer floated over Rival Arena and Block Realm", desc: "The hub has a pointer you can drive with a controller so a gamepad can work the menus. Both new 3D games read the controller directly once you're playing, so that pointer should step aside \u2014 but neither was telling it to, and it sat on top of the game drifting around and swallowing stick input. It now hides the moment a match or a world starts and comes straight back in the lobby, the pause menu, and when you leave, so you can still press buttons with a controller everywhere it makes sense. Gun Game Arena already did this; the two new games simply weren't calling the same thing." },
      ],
    },
    {
      date: "2026-08-31",
      entries: [
        { emoji: "\u{1F512}", time: "00:06", title: "Fixed: a way to read the accounts file straight off the server", desc: "The server refused to serve /data/profiles.json \u2014 but it checked the address for that exact spelling *before* tidying it up, so a slightly different spelling of the same path walked straight through and returned the whole file: every account's name, email, avatar, recovery codes and password hash. Because sign-in compares that hash directly, handing it out is the same as handing out the password. The same gap served the server's own source code and its private key, and the source was confirmed readable on the live site. It now works the other way round: the address is resolved first, and only a short list of folders that are meant to be public \u2014 the games, styles, scripts, icons and downloads \u2014 can be served at all, so adding a new folder to the project can never quietly publish it. Nothing about the site changes for you; everything that should load still loads." },
        { emoji: "\u{1F504}", time: "00:05", title: "Fixed: updates didn't show up until you reloaded twice", desc: "The offline cache was cache-first for everything. That's right for the versioned files \u2014 a new version is a new URL, so it can never go stale \u2014 but wrong for the page itself, which carries no version string. The result was that a deployed change sat there invisible: the server was serving the new hub while browsers kept showing the previous one, and it only corrected itself after the cache name moved and you loaded the page twice. It got worse once games got their own short links, because each one was a separate cache entry pinning its own copy of the stale page. Page loads now go to the network first and fall back to the cache only when you're actually offline, so an update appears the moment you open the site." },
        { emoji: "\u{1F3AE}", time: "00:04", title: "Rival Arena: controller support, and it aims with you", desc: "Gamepads simply weren't read at all in the new shooter \u2014 fixed. Left stick moves, right stick looks, RT fires, LT aims, A jumps, X reloads, LB/RB swap weapons, Start pauses. Touchscreens get a full control set too: drag the left half of the screen to move, the right half to look, with buttons for fire, aim, jump, reload and swap. Both also get aim assist, the way a console shooter does it: the crosshair slows down when it's near an enemy and drifts gently toward them, strong enough to make a thumbstick competitive and far too weak to aim for you. It won't reach through walls, and mouse and keyboard deliberately don't get it \u2014 that wouldn't be aim assist, it would be an aimbot." },
        { emoji: "\u{1F50D}", time: "00:03", title: "Rival Arena: you can scope in now", desc: "Right-click (or LT on a pad, or the \u{1F50D} button on touch) aims down sights. It cuts your spread by about three quarters, so it's worth doing on every gun, and slows your movement and look speed to match. Each weapon zooms by a different amount, and the Sniper gets a real scope \u2014 the gun drops out of view and you get the black surround and crosshair instead of just a zoom. The crosshair tightens as you aim so you can see the spread change." },
        { emoji: "\u{1F3C6}", time: "00:02", title: "A keys leaderboard, and dev tools for keys", desc: "The Keys panel now shows the top key holders across everyone signed in, riding on the hub's existing leaderboard system rather than a new one. Signed-in dev accounts also get a small tools row there to set, add or clear their own balance \u2014 gated on a real server-verified dev account, the same check Kart Circuit's cheats use, so it exists to exercise the crate economy without grinding five games a day first." },
        { emoji: "\u{1F4E6}", time: "00:01", title: "A proper Windows app again \u2014 and it stays off your C: drive", desc: "Windows has been a .zip for a few versions because the installer couldn't be built here. There's now a single-file \u201851 Mimi Games.exe\u2019 you just run \u2014 no install, no extracting a folder first. It's also genuinely portable: put it on a D: drive or a USB stick and everything it saves (profiles, keys, saved worlds, every game's progress) goes in a folder beside it instead of into AppData on C:. Only caveat Windows itself imposes: a self-extracting .exe unpacks to your temp folder while it runs. Nothing is kept there, and the .zip build avoids even that." },
        { emoji: "\u{1F4C4}", time: "00:00", title: "The repository has proper docs now", desc: "Added a licence, contributing guidelines, a code of conduct, a security policy, issue templates for bugs and ideas, and a pull request template \u2014 the things GitHub asks every project for so anyone landing on it knows what it is and how to help." },
      ],
    },
    {
      date: "2026-08-30",
      entries: [
        { emoji: "\u{1F511}", time: "00:03", title: "Keys \u2014 earn them by playing, spend them in games", desc: "Play 5 different games in a day and you're awarded 10 keys. Different games, not five launches of the same one, because otherwise opening and closing Snake five times would pay out. Your balance sits in the dock next to Settings, and the panel there shows how far through today you are. The wallet follows whoever is signed in, so two people sharing a device don't share keys. The first place to spend them is Rival Arena's crate; more games will take them later." },
        { emoji: "\u{1F3AF}", time: "00:02", title: "Rival Arena \u2014 a proper 3D arena shooter", desc: "A new fast first-person shooter against bots, built on a real 3D engine rather than the wall-casting trick Gun Game Arena uses: actual height, cover you can climb onto, and sightlines across the map. Four weapons that genuinely play differently (SMG, Rifle, Shotgun, Sniper) with their own recoil, spread, magazines and reloads; headshots count double; sprint, crouch and jump; hit markers, damage numbers, a kill feed and streaks. Three match sizes from 5 bots up to 10. Spend keys on crates to unlock weapon skins across four rarities \u2014 cosmetic only, on purpose: a currency that bought damage would turn a daily bonus into a chore. Gun Game Arena stays exactly as it is, because it's the one with networked team play for up to 20 people." },
        { emoji: "\u26CF\uFE0F", time: "00:01", title: "Block Realm \u2014 a voxel sandbox", desc: "Build a world from a seed and a world type (Normal, Superflat, Islands or Amplified), pick Survival or Creative, and dig. It's a real chunked voxel engine: terrain generated from noise, per-face meshing with baked ambient occlusion, block-accurate collision, and voxel ray picking for whatever you're aiming at. Trees, beaches, water you can swim in, twelve block types, and a hotbar that fills as you mine in Survival or is unlimited in Creative, where you can also fly. Vibrant Vision swaps the whole palette, sunlight, sky and fog for a richer look, and can be toggled mid-game from the pause menu. Worlds and everything you build in them are saved \u2014 only the blocks you actually changed, since the rest regenerates from the seed." },
        { emoji: "\u{1F522}", time: "00:00", title: "Fixed: the hub had been undercounting its own games", desc: "The front page said \"80 games, one hub\" and the console warned on every single load that it expected 80 and found more \u2014 both stale since the count passed 80 some time ago. The tagline now reads the real number, and the check that guards against a game file silently failing to load is a tripwire again rather than permanent noise." },
      ],
    },
    {
      date: "2026-08-29",
      entries: [
        { emoji: "\u{1F517}", time: "00:04", title: "Every game has its own link now", desc: "The hub is a single page, so all 85 games sat at the same address \u2014 \"come play Snake\" could only ever be a link to the front door, and Kart Circuit's own URL was /games/mario-kart/index.html. Games now live at short addresses you can actually send someone: /snake, /2048, /tic-tac-toe, and Kart Circuit at /kart-circuit. Opening a game puts its address in the bar, Back takes it out again, and loading one of those URLs cold opens straight into that game. Deliberately one segment rather than /play/snake: a page served from a deeper path looks for all its files in that deeper path, so /play/snake loaded a completely blank hub \u2014 found by actually loading it, and the flat form has nothing to get out of sync." },
        { emoji: "\u{1F9CA}", time: "00:03", title: "A proper background for the hub", desc: "The backdrop was a flat dark rectangle. There's now depth to it: shaded 3D blocks tumbling slowly through the space behind the shelf, a drifting wash of Joy-Con colour in the corners, fine dust rising in front at three different speeds, and a slow pass of light across the whole thing. Move the mouse and the layers shift against each other; hover a game and the room picks up that game's colour. It's all drawn here rather than pulled from a 3D library \u2014 the one in this repo is 670 KB, and a backdrop has no business being the biggest thing on the page \u2014 and it stops drawing entirely when the tab is hidden, a game is open, or you've asked for reduced motion." },
        { emoji: "\u{1F3AE}", time: "00:02", title: "Kart Circuit: the controls are on the pause screen now", desc: "Pausing used to show the word PAUSED and how to unpause \u2014 the one thing you already knew. Everything you might actually have paused to look up was buried in the pre-race menu, behind quitting the race. Pausing now shows the full control list on a proper panel, and it adapts to how you're playing: your own seat's keys (each split-screen seat has a different set), your real gamepad bindings including any you've remapped, and steering. The HUD and mini-map step out of the way while it's up instead of sitting on top of it." },
        { emoji: "\u{1F30D}", time: "00:01", title: "Kart Circuit: Play Online \u2014 race strangers regionally or worldwide", desc: "Wireless multiplayer only ever worked if someone shared a room code with you. There's now real matchmaking: pick Regional to be put with racers near you (worked out from your device's time zone, no location permission and no sign-up), or Global for anyone anywhere. You're dropped into a lobby with whoever else is searching, the track is picked at random so nobody's stuck with the first person's choice, and the race starts on its own once at least two racers are in \u2014 with a countdown the server runs, so everyone sees the same number. A started race closes to new arrivals so nobody lands on a track mid-lap, and if whoever opened the lobby leaves, the next racer takes over rather than the whole thing stalling." },
        { emoji: "\u{1F3C1}", time: "00:00", title: "Kart Circuit's menu is one choice at a time now", desc: "The pre-race screen asked for everything at once \u2014 mode, player count, gamepad mapping, driver, kart, colour, cup, all fourteen tracks, difficulty \u2014 on one card taller than the window, so whatever you wanted was always below the fold and whatever you'd already picked was never obvious. It's now a Mario Kart 8-style flow: pick a mode, then one decision per screen, with Back/Next, a progress bar, and a summary of every choice before you commit. Each mode only walks the steps it needs \u2014 an online race has no track to pick, a solo one has no lobby to wait in \u2014 and choosing a cup drops the track screen entirely instead of leaving a dead step. Start Race sits in the footer where it can't scroll away, and chat and the camera strip move inside the lobby panel rather than floating on top of it." },
      ],
    },
    {
      date: "2026-08-28",
      entries: [
        { emoji: "\u{1F3C1}", time: "00:02", title: "Kart Circuit races now look like Mario Kart World", desc: "The daylight look was really a dusk one wearing a blue sky \u2014 a near-black horizon, hills painted almost black, and grass darker than the road it ran alongside. Rebuilt around how Mario Kart World actually lights its world: sunlit and high-key, with distance washing things toward the pale bright horizon instead of toward black. Big soft cumulus clouds drift across the sky (each track tints its own, so Rainbow Skyway and Volcano Rim don't get daylight-white clouds pasted onto them), the road is warm light asphalt clearly brighter than the verge either side, and the fill light comes up so the shaded side of a kart no longer falls to near-black just for facing away from the sun." },
        { emoji: "\u{1F3AE}", time: "00:01", title: "Kart Circuit: a real racing HUD, and a proper starting-light countdown", desc: "The on-screen readout was four lines of text in a bordered box in the corner \u2014 place, lap, item, coins \u2014 which is a debug panel, not a HUD. Rebuilt in Mario Kart World's layout: the item you're holding sits in a big rounded slot top-left with your coins under it, the lap is a pill top-right, and your place is an enormous outlined number in the bottom-right corner where you can read it mid-corner without looking away from the track. Speed and controller name are diagnostics, so they moved small and quiet along the bottom edge. The race start is now three starting lights filling in over the countdown, with each number punching in oversized and settling, rather than a flat number fading in and out." },
        { emoji: "\u{1F3C6}", time: "00:00", title: "Kart Circuit's menu is now Mario Kart 8's", desc: "The pre-race screen was a dark glass card on a dimmed background. It's now MK8's front end: a bright blue stage with light rays sweeping across it, a thick cream-bordered panel, a red title banner, and chunky pressable buttons with a solid bottom lip. Gold is the one selection color throughout, so the cup, track, difficulty and driver you've picked are obvious at a glance instead of being a slightly lighter shade of the same card, and Start Race is unmistakably the button that starts the race." },
        { emoji: "\u{1F535}", time: "00:00", title: "The hub is now the Switch 2 home menu", desc: "Redesigned end to end to match the console's own home screen. The games are a shelf of big rounded-square icons, each with its own color and its name printed underneath, and the one you're on scales up inside a white selection ring. The system buttons \u2014 Music, Settings, What's New, Download App, Profile, Play Together \u2014 left the top bar for a dock along the bottom, as round icons that name themselves when you hover them, and the top bar now carries a round user icon on the left and a live clock, wi-fi and battery readout on the right (real battery level, where your device reports one). Background, panels, menus and type all followed. Everything works exactly as it did \u2014 the dock holds the same buttons, just moved." },
      ],
    },
    {
      date: "2026-08-24",
      entries: [
        { emoji: "💾", time: "00:03", title: "Accounts now survive the live site restarting", desc: "Render's free hosting plan resets its disk on every redeploy and whenever the service wakes from sleep — accounts, leaderboards, and cakes were quietly getting wiped out from under people (confirmed: one created earlier today was already gone by the afternoon). Profiles/leaderboards/cakes now also mirror to a small free Redis database, checked first on startup and written to on every save, so a reset no longer means starting over. Confirmed live: wiped local storage entirely and restarted — the test account was still there, pulled back from the durable copy. Local hosting (LAN/desktop app) is unaffected — this only activates when a durable store is actually configured." },
        { emoji: "🔁", time: "00:02", title: "Fixed: the Windows app's auto-update never actually worked", desc: "The installed app checked for updates against this WSL2 dev machine's own address — reachable from inside that dev environment, never from the real installed app on your actual Windows PC. So every update this whole session had to be delivered by hand instead of the app finding it on its own. Now checks a real public GitHub Releases feed instead, the same place the Download App links now point — works the same regardless of which machine or network you're on. Also dropped a TLS-trust bypass that only existed to work around that old dev-only address's self-signed certificate — the real feed doesn't need it." },
        { emoji: "🔧", time: "00:01", title: "Fixed: every Download App link 404ing on the live site", desc: "downloads/ (where the actual app builds live) was never part of what deploys to Render — it's in .gitignore (some builds are 300MB+, over GitHub's normal file-size limit), so the live site's copy of that folder was simply empty. Every Download App link — Windows, macOS, Linux, Android phone/TV, and now VR — was quietly a dead link there, even though the same button worked fine locally. Fixed by hosting the actual builds as GitHub Release assets instead and pointing the menu at those, so they resolve the same way no matter where the page itself is served from." },
        { emoji: "🥽", time: "00:00", title: "Meta Quest VR app added to Download App", desc: "The VR build (same hub, packaged for Quest, already being sideloaded manually) is now a real option in the Download App menu alongside Windows/Mac/Linux/Android phone/TV — grab the .apk straight from the site instead of needing it handed to you separately." },
      ],
    },
    {
      date: "2026-08-22",
      entries: [
        { emoji: "🔧", time: "00:20", title: "Fixed: Server address setting was ignored by sign-in, leaderboards, and multiplayer", desc: "The new Server address override (just added) correctly redirected the actual network calls to the backend you typed in — but every place that decides whether to *show* the sign-in form, leaderboards, or Play Together instead of a \"needs the full hosted version\" notice was still only checking whether the page loaded from the static GitHub Pages preview, with no idea an override existed. So setting a real backend address didn't actually unlock anything in the UI — it kept showing the static-preview notices regardless. Fixed: a configured Server address now counts as having a real backend, same as being on a fully self-hosted site." },
        { emoji: "🔌", time: "00:19", title: "Server address setting — no more rebuilding the app for a new URL", desc: "Every Android build (phone, TV, VR) needed a full rebuild whenever the backend's address changed — a temporary tunnel URL, a home-network IP. Settings now has a \"Server address\" field: type the current one in and reload, and the app finds accounts, leaderboards, and multiplayer there instead of wherever it was originally built to point at. Leave it blank and everything behaves exactly as before — same origin the page loaded from. Also means the Android apps can now ship pointed at a permanent, stable address (this site) and still reach a private backend when you set one, falling back to solo/local play when you don't — the same graceful behavior the static GitHub Pages preview already has." },
        { emoji: "📡", time: "00:18", title: "Multiplayer relay now works over a plain-HTTP tunnel too", desc: "The wireless multiplayer relay only ever listened on the main HTTPS server. A tunnel service (ngrok, localhost.run, and similar) terminates its own TLS and expects a plain-HTTP origin behind it — which this app already runs, for the desktop update feed — but that port had no multiplayer relay attached, so games worked over a tunnel while Play Together and Kart Circuit's wireless racing silently couldn't connect. Both ports now share the exact same relay and room list, so there's nothing separate to keep in sync." },
        { emoji: "🏁", time: "00:17", title: "Fixed: laps not counting reliably in Kart Circuit", desc: "Crossing the finish line only ever counted if it happened through a narrow strip roughly half the actual track's width, centered on the road — every map's finish gate banner was drawn narrower than the real road, and the lap logic was checking against the banner instead of the road. A totally normal racing line — wide on the entry, tight on the apex, drafting past a bot on the final straight — easily crosses outside that strip, which silently rejected the lap while leaving it still \"armed\" to count on some later pass instead. That's exactly the reported bug: one lap wouldn't register, but it wasn't lost either — it would suddenly catch up a lap later, on every map, every device. The checkpoint loop already fully guards against a fake lap (you can't skip it), so the extra width restriction wasn't protecting anything — removed. Confirmed against every map's own numbers: the old strip was consistently about half the real road width." },
        { emoji: "🥽", time: "00:16", title: "Fixed: no race-start countdown in VR", desc: "The \"3, 2, 1, GO!\" countdown before a race only ever drew onto the flat 2D screen, which a VR headset never sees — so racing in VR meant the race quietly started and counted down with no visual sign of it at all. The in-VR dashboard already mirrors the waiting screen, pause, item notices, and results for exactly this reason (headset can't see regular on-screen UI), but the countdown was missed when that was built. Added — the countdown now shows on the in-headset dashboard too, matching the flat-screen version." },
        { emoji: "🛠️", time: "00:15", title: "Fixed: Android app downloads missing from the desktop app", desc: "The Download App button was hidden entirely whenever the hub was already running inside the desktop app itself — sensible back when the menu only had Windows/Mac/Linux installers (downloading the app from inside the app doesn't make sense), but no longer true once the Android phone/tablet and TV entries were added: those are useful regardless of which desktop platform you're already on. The button now only hides on the static GitHub Pages preview, where those files genuinely aren't available." },
        { emoji: "📱", time: "00:14", title: "Android phone/tablet and Android TV apps", desc: "Two new installable Android apps, added to the Download App menu alongside Windows/Mac/Linux: a phone/tablet app and a separate Android TV app (shows up on the TV's own app launcher with a proper banner, not just a phone app squeezed onto a big screen). Both wrap the same hub you already play in a browser — built as Trusted Web Activities, Google's standard way to package a PWA as a real installable app, so it's the same code and games, not a rewrite. Neither is on the Play Store (that needs a Google developer account and review), so both are direct APK downloads — Android will ask you to confirm \"install from unknown sources\" the first time, same as any app installed outside the Play Store. They currently point at the static GitHub Pages preview, so sign-in/leaderboards/multiplayer show the same \"needs the full hosted version\" note the browser preview does; every game itself plays exactly the same." },
        { emoji: "🛡️", time: "00:13", title: "Rate limiting on the API, and the hub is ready to publish", desc: "The server had a known gap: no rate limiting on any API route, fine on a home LAN but not safe to expose on the open internet. Added a per-IP limiter — 120 requests/minute on the general API, a tighter 15/minute on the sensitive profile actions (sign up, log in, change password, recover, passkey verify) where brute-forcing matters most. Confirmed live: the 16th login attempt in a minute from the same IP gets turned away with a clear \"try again\" response instead of being processed. Also added proper page description and social preview tags (Open Graph/Twitter card) so a shared link shows something real instead of a blank title. Groundwork for putting the hub on a real URL rather than just this dev machine." },
        { emoji: "🏎️", time: "00:12", title: "Kart Circuit: fixed Fly, plus God Mode, Infinite Items, and bot/opponent Speed", desc: "Fly used to just disable falling/collisions and boost speed — the kart never actually left the ground, so it looked and felt exactly like driving fast and invincible, not flying. Now it really lifts the kart into a hover. That surfaced a real camera bug on the way: the 3D camera's height and look-at target were both hardcoded, never accounting for how high the kart actually was, so once Fly lifted it high enough the kart flew straight out of frame — confirmed live, the view was almost entirely sky. Fixed so the camera rises and tilts to follow, at the same rate as the target so the original viewing angle holds regardless of altitude (a nice side effect: jump and glide tricks frame better now too, not just Fly). Two new toggles, distinct from Fly on purpose: God Mode makes you immune to rockets/oil/hazards/lightning specifically while you keep driving normally on the track (Fly's no-clip/off-track immunity is a different, broader thing); Infinite Items keeps your item slot full after every use, with a dropdown to pin it to one specific item instead of just repeating whatever you last used. Speed can now target any bot (or all of them at once) via a dropdown populated with that race's real roster, not just your own kart — networked human peers aren't offered, since their position comes from their own client, not local physics, so there'd be nothing for a local override to actually do." },
        { emoji: "🛠️", time: "00:11", title: "Dev Cheats in every game", desc: "Every game in the hub (all 80+, apart from Calculator/Notes/Timer & Stopwatch, which aren't games, and Kart Circuit, which already had its own Fly/Speed cheat panel) now has a small \"Dev Cheats\" panel — visible only when a real, server-verified dev profile is signed in — with at least two cheats wired into that game's actual state: force a win, reveal a hidden hand or solution, add score, go invincible, skip a level, and more, whatever fits each game. Built on a new shared ctx.devCheatPanel() helper (js/engine.js) any game can use, so the panel looks and behaves consistently everywhere instead of each game inventing its own. Every one of the 85 game files was verified to still parse correctly, and a spot-check across several (Snake, Old Maid, Sudoku, and others) confirmed the panel renders and each cheat visibly changes real game state — not just a label that does nothing." },
        { emoji: "🔑", time: "00:10", title: "Fixed signing in with the same profile from another device", desc: "Password hashing had two completely different code paths that were supposed to produce the same result and quietly didn't: the real one uses the browser's built-in SubtleCrypto (SHA-256), which only exists in a \"secure context\" — https:, or http: to localhost specifically. Joining another device's hub over the LAN is plain http:// to that device's LAN IP, which does not count as secure, so SubtleCrypto was silently unavailable there and the code fell back to a completely different, much weaker hash instead — same name and password typed correctly, but a passwordHash that could never match what the host device stored at signup. Replaced the fallback with a real, pure-JS SHA-256 (verified byte-for-byte against Node's own implementation), so both paths always produce the identical hash. Confirmed live end-to-end: a hash computed the fallback way is accepted as a valid login for an account created the SubtleCrypto way. Anyone who hit this before the fix will need to sign up again once — the mismatched hash already on file for that account doesn't retroactively fix itself." },
        { emoji: "🕹️", time: "00:09", title: "Gamepad cursor: fixed a controller that made it drift upward on its own", desc: "Confirmed live with the exact controller: an 8BitDo pad in a raw/non-standard report mode exposed 9 axes instead of the usual 4, with a real, correctly-centered stick on axes 0/1 — but also an analog trigger reported as axis 3, permanently sitting at -1.00 at rest (a normal idle value for a trigger-as-axis, not a stick). A fallback added for a different 8BitDo quirk (where the stick lands on axes 2/3 instead of 0/1 on some controllers) saw that stuck -1.00, mistook it for stick input, and drove the cursor upward continuously with the stick never touched — same root cause hit the right-stick scroll axis too. Both now only trust that fallback for controllers reporting exactly the 4-axis shape the original quirk was written for; anything else keeps the real, correctly-centered axes rather than confidently grabbing the wrong one." },
        { emoji: "🚗", time: "00:08", title: "Kart Circuit: bots no longer jam up at the start line", desc: "Confirmed live: bots would barely move for the first 15-20 seconds of a race, still nearly on top of the starting grid while the player was most of a lap ahead — not a display glitch, they were genuinely stuck. The starting grid packs every racer within each other's AI avoidance range at once (by design, that's what a grid is), so at full strength their avoidance steering fought itself in every direction simultaneously, and they also all read the whole pack in front of them as \"traffic\" and throttled down for it — a self-reinforcing jam. Both eased off for the first few seconds of a race, just long enough for the pack to pull apart under forward progress, then back to normal open-track dodging." },
        { emoji: "🔒", time: "00:07", title: "Dev profiles now need a real password to create", desc: "Signing up as a dev used to be a plain checkbox — anyone could tick \"I'm the developer\" (or just call the API directly) and get dev-only capabilities, including the Admin panel, with nothing checking it server-side, the only place that check can actually mean anything. Dev signup now requires the real dev password, verified on the server the same way a profile's own password is (hashed before it's ever sent, never stored or transmitted in the clear)." },
        { emoji: "🛸", time: "00:06", title: "Kart Circuit: a Dev Cheats panel for signed-in dev profiles", desc: "A small panel in the corner, visible only when a real dev profile (see above) is signed in: Fly turns off falling, off-track penalties, and collisions with the pack entirely, for testing track layouts and cameras without fighting the race itself; Speed sets your kart's speed directly, overriding the normal accel/decel. Confirmed live: toggling Fly correctly shows/hides for dev vs. non-dev accounts, and updates within a couple seconds of signing in or out. The same dev-profile check is now available to any other game too (ctx.isDevProfile() in the shared engine) — Kart Circuit is the first to use it, not the only one that can." },
        { emoji: "🏁", time: "00:05", title: "Kart Circuit: real starting grids, and racers no longer spawn off track", desc: "Confirmed live: bots and the player alike could immediately read as off-track the instant a race began, before ever touching the controls. Two compounding bugs, both fixed. First, every map's starting grid used to come from a handful of hand-placed points (however many that map happened to define) plus a rough, inconsistent fallback for whoever didn't fit — replaced everywhere with one real Mario-Kart-style grid generator: two karts wide, staggered rows extending back from the start line, built the same way on every map. Second, and the actual root cause of the false off-track reports: that fallback (and the game's own off-track distance check) measured how far back to place each row in raw checkpoint-sample units, which don't mean the same real distance on every track — on a tightly-subdivided map like Neon Loop, a back-row racer could land far enough from the nearest sample the game was willing to check that it read as off the track entirely. Both the grid and the underlying position search now work in real world distance, with a safety net that re-checks the whole track if a result ever looks implausible, so this can't reappear on some other map/racer-count combination the same way." },
        { emoji: "🏎️", time: "00:04", title: "Kart Circuit: wireless multiplayer now works properly in VR", desc: "The in-VR dashboard's \"click the thumbstick to start\" prompt is now multiplayer-aware: connected as the host, it shows your room code; connected as a joiner, it says you're waiting for the host instead of implying you can start it yourself. That's not just cosmetic — clicking Start Race (on the flat page or in VR) as a joiner had no host check at all, so it silently started your own race locally, out of sync with everyone else in the room. Only the host's real start (which every joiner already receives and reacts to correctly) can start the race now. Racer rendering, camera, and position sync were already shared code with no VR-specific path, so other players' karts were already showing up correctly in a headset — this closes the actual gap, which was entirely in the pre-race controls." },
        { emoji: "🏁", time: "00:03", title: "Kart Circuit: fixed the flickering track in 3D", desc: "Confirmed live: the road mesh drew a full-width \"shoulder\" band and then the narrower road and curb bands directly on top of it, at the exact same height — that's overlapping, perfectly coplanar geometry, and the GPU has no consistent way to decide which layer wins at a given pixel, so it flickered between them as the camera moved. The shoulder band now sits a fraction below the road surface, enough depth separation to fix the flicker with no visible seam." },
        { emoji: "🏎️", time: "00:02", title: "Kart Circuit: race results and item pop-ups now show up inside VR", desc: "Two more things that only ever showed on the flat page behind the headset, confirmed live by actually racing: finishing a race in VR dropped straight to a generic \"click to start\" prompt with no sign of whether you'd won, and using an item (star power, a lightning strike, a Boo steal, ...) showed nothing at all, since those notices only ever set the flat status bar's text. Both now mirror into the same in-VR dashboard panel already showing lap/place — the real result text when a race ends, and the same item notice text while one's active." },
        { emoji: "🧮", time: "00:01", title: "Calculator, Notes, and Timer & Stopwatch now sit right on the front page", desc: "The very first screen you see (the search-style front page, next to the \"51 Mimi Games\" tile) now has its own tiles for Calculator, Notes, and Timer & Stopwatch — click one and it opens straight into that tool, no need to go through Play Solo and the full game grid first. They still live in the hub too, under the Apps category (renamed from Tools), for anyone who'd rather browse to them that way." },
        { emoji: "🧮", time: "00:00", title: "...and their own Start Menu shortcuts", desc: "Each app also has its own shortcut in the Windows Start Menu, next to the main \"51 Mimi Games\" one — \"Calculator (51 Mimi Games)\", \"Notes (51 Mimi Games)\", and \"Timer & Stopwatch (51 Mimi Games)\". Clicking one launches the app straight into that tool." },
      ],
    },
    {
      date: "2026-08-20",
      entries: [
        { emoji: "🎂", time: "00:06", title: "Two new games: Field Tag 3D and Cake Bakery", desc: "🏃 Field Tag 3D: a pseudo-3D open grass field (same rendering technique as Zombie Highway 3D) where you chase down fleeing runners before a 60-second clock runs out — WASD/arrows, touch drag-to-steer, or a gamepad, tag radius catches a runner and a new one appears elsewhere, best score reports to this game's leaderboard. 🎂 Cake Bakery: decorate a cake (4 base flavors, 5 topping slots cycling through 8 toppings) and publish it to a real shared feed everyone sees — backed by a new server-side store (data/cakes.json, same load/save pattern as leaderboards and profiles), not just saved locally. A second mode, Match Streak, shows you someone else's actual published cake and challenges you to rebuild it exactly; get it right and the streak continues with a new cake, get it wrong and the run ends, with your best streak reported to the leaderboard. Publishing requires being signed in (cakes go out under your real profile name), same trust level as everything else profile-linked in this hub." },
        { emoji: "🧰", time: "00:05", title: "A new Apps section: Calculator, Notes, and Timer & Stopwatch", desc: "Three non-game utility apps, sitting in the game grid under a new Apps category (categories are derived automatically from whatever games declare, so this needed no separate plumbing). 🧮 Calculator: standard arithmetic with keyboard support. 📝 Notes: quick sticky notes that autosave to this device, create/edit/delete. ⏱️ Timer & Stopwatch: a countdown timer with an alarm sound, and a stopwatch with lap splits, as two tabs in one tool." },
        { emoji: "🏎️", time: "00:04", title: "Kart Circuit: a real in-VR cockpit, working start/pause, and a placement bug fixed", desc: "VR was further along than it looked but mostly unusable in practice — confirmed live, one issue at a time. The big one: the entire per-frame update/render loop was gated behind \"if not racing, do nothing at all\" — meaning before a race started, literally nothing updated or rendered in VR: no camera, no HUD, no way to even start the race, since the flat Start Race button is invisible once a headset owns the display. Fixed so a live headset keeps updating and rendering regardless of race state. On top of that: added a procedural steering wheel and dashboard readout you can actually see from inside the cockpit (previously just an empty view), start/pause now work via a thumbstick click (deliberately not the trigger, since that's also accelerate — edge-triggering off the same button meant pressing the gas also paused the race), and the \"waiting to start\"/\"paused\" HUD text was overflowing clean off its texture and rendering as nothing visible, now sized to fit. Separately, fixed a real placement bug affecting everyone, VR or not: race position was computed with an unconstrained nearest-point search across the whole track, which could snap to a totally different lap segment wherever the track passed close to itself, causing a sudden, wrong placement jump (confirmed live: 1st to 24th mid-lap) — now constrained to a window around the racer's actual next checkpoint. Also added a new item: 👻 Boo, which steals coins from the nearest racer ahead of you." },
        { emoji: "🕹️", time: "00:03", title: "The gamepad cursor no longer locks onto the wrong controller", desc: "On a setup with more than one gamepad-like device registered (DS4Windows, Steam Input, and similar virtual-controller drivers can add an inert second slot alongside a real controller), the cursor could lock onto whichever one happened to be listed first — showing the cursor (a gamepad IS connected) but never responding to the stick, because that particular slot never reports real input. Now, when more than one pad is connected, it prefers whichever one is actually showing live input at that moment, and only falls back to \"just the first one\" when nothing's active on any of them — a real controller on its own is unaffected either way." },
        { emoji: "🌐", time: "00:02", title: "The private page viewer renders modern sites properly and keeps search results private", desc: "Two real bugs, both confirmed live. First: the viewer's fetch requests went out with a made-up User-Agent string identifying it as a private-viewer tool rather than a real browser — sites like Google sniff that and serve their legacy/degraded fallback UI to anything they don't recognize, which is exactly why pages looked like they were rendering on an old OS and Google Maps came up without its sidebar. Now sends a real, current Chrome User-Agent. Second: Google's own search box navigates via a JS window.open() call rather than a plain link or form submit, which the viewer didn't intercept — since the frame allows popups, this opened Google's real results in a genuine separate browser tab instead of staying inside the private viewer. window.open() is now caught and routed through the same private-fetch relay as every other link — and, since a real window.open() normally returns a usable object that plenty of sites call something on right after, the intercepted version returns a harmless stand-in instead of null, so it can't throw and silently kill the rest of that page's own script the way a bare null did at first." },
        { emoji: "🍰", time: "00:01", title: "Passkeys and saving your email actually do something now", desc: "Adding a passkey, removing one, saving a profile picture, saving an email, and generating a recovery code all quietly did nothing in the packaged desktop app — confirmed live, no error, no dialog, just silence. The cause: every one of those flows asks for your password via window.prompt(), and Electron — unlike a real browser — never implements a native dialog for window.prompt() at all; calling it just silently returns null with no UI ever shown. Replaced with a real in-page dialog that works identically in the desktop app and a browser tab, wired into all seven places this hub used to call window.prompt()." },
      ],
    },
    {
      date: "2026-08-16",
      entries: [
        { emoji: "🏆", time: "00:04", title: "Achievements, global leaderboards, friends, and Kart Circuit colors", desc: "Four new features, all built on the existing profile system so they follow you across devices. 🏆 Achievements: 12 badges, mostly hub-level (games played, profile age, friends, leaderboard rank) rather than per-game — check the new Achievements button. 📊 Leaderboards: real cross-profile high-score boards for Snake, 2048, Reaction Test, Bowling, and Darts (more games can opt in later — this is a starting set, not the ceiling). Scores are self-reported by the browser, same trust level as everything else here — no server-side anti-cheat, stated plainly rather than pretending otherwise. 👥 Friends: follow anyone by exact name (no public directory — you have to already know who you're looking for), no approval needed to follow, and once you follow each other you're mutual friends — only then do you see if they're online or which room they're hosting, reusing the existing room-code system rather than building a new invite mechanism. 🎨 Kart Circuit: pick your kart's color from the setup screen, synced to your profile — and along the way, fixed a real bug where your chosen color never actually reached other racers in a wireless race (the join message was hardcoding everyone to the same default color). Color choice locks in before the race starts and applies to the kart body only, not full skins. Tested end-to-end with two real signed-in profiles: follow → mutual friends → online status, a submitted score showing up on a different profile's leaderboard view, a client-side achievement and a server-verified one both unlocking correctly, and a chosen kart color actually appearing on another player's screen in a live multiplayer race." },
        { emoji: "🥽", time: "00:02", title: "Kart Circuit: real VR headset support (WebXR)", desc: "Kart Circuit — the one game in the hub built on a real 3D engine — now supports genuine immersive VR on a WebXR-capable headset (Quest Browser and similar). Click Enter VR (only shown when a headset is actually detected) and race from a real stereo cockpit view, steering with your controller's thumbstick and trigger/grip/face buttons instead of a keyboard or gamepad. The camera locks to the existing Hood view while in VR (the one mode that already looks from the kart rather than at it) and a small lap/place readout floats in the cockpit like a dashboard gauge. Split-screen and VR don't mix — a single stereo headset view has no equivalent to multiple flat viewports — so VR is only offered with one local player, same as it's hidden entirely in 2D map mode or on a browser/device with no VR support at all (iOS Safari has none, so nothing changes there). Every existing flat-screen path — all 4 camera modes, split-screen, 2D map mode, wireless multiplayer — was tested end-to-end afterward with zero regressions. The actual in-headset feel (distance, comfort, controller mapping) still needs real hardware to judge — no headset was available to test with directly, so that part's on you." },
        { emoji: "🔐", time: "00:01", title: "Passkeys now actually work in the desktop app", desc: "Adding a passkey in the downloadable desktop app failed instantly with \"This is an invalid domain\" — confirmed live. The cause: the app was loading the hub from a raw IP address (127.0.0.1), and WebAuthn's spec flatly forbids using a literal IP address as the passkey domain, no exceptions. Fixed by having the desktop app load the exact same local server through \"localhost\" instead — a real, spec-allowed domain, same machine either way. Confirmed end-to-end on a real Windows build: creating a passkey now correctly reaches the real Windows Hello/fingerprint prompt instead of being rejected before it ever gets there. Recovery email saving was checked too and was already working correctly — no bug found there." },
        { emoji: "🔄", time: "00:00", title: "The desktop app now updates itself", desc: "No more manually re-downloading and reinstalling every time something changes — the desktop app now checks for a new version shortly after launch, downloads it in the background, and asks to restart and apply it (or just applies it next time you quit, if you'd rather keep playing). This meant switching the desktop build from a plain unpacked folder to a real Windows installer, since a genuine install — with an uninstaller and a place Windows tracks it — is what auto-update actually needs to work against. First install after this update is still a one-time manual download; every version after that should update on its own." },
      ],
    },
    {
      date: "2026-08-15",
      entries: [
        { emoji: "⬇️", time: "00:07", title: "A real Download App button in the task bar, plus the private page viewer actually works now", desc: "🆕 What's New now sits next to a genuine ⬇️ Download App button — click it and pick Windows/macOS/Linux, and the matching desktop build downloads straight into your Downloads folder as a real file, no browser install-prompt involved (that's the separate PWA install from the last update; this is the actual downloadable app). Also fixed a real problem in the private page viewer: it could show a page's raw HTML but nothing JS-dependent ever rendered, which in practice meant most of the modern web — Google, YouTube, DuckDuckGo, all confirmed broken — showed blank. Scripts are now allowed to run (most real sites need them to render at all), deliberately NOT combined with same-origin access, which is what keeps a script-enabled page from ever being able to reach into the hub's own storage — a known way sandboxes get bypassed when those two are combined carelessly. That surfaced two more real bugs, both fixed: sites that read document.cookie/localStorage without expecting it to throw (not just be empty) crashed outright before rendering anything — DuckDuckGo specifically, confirmed live; and every page after the first one navigated away from the private proxy entirely once you clicked anything, hitting the exact same problem all over again with no fix applied. Both fixed with a small script injected into every fetched page itself — safe to run same-document, no special access needed — that patches cookie/storage to fail quietly instead of throwing, and relays every link click and GET-form submission back through the same private fetch instead of letting the frame navigate on its own. Confirmed end-to-end: typed google.com, got a fully rendered, working Google; typed duckduckgo.com, searched from its own search box, and landed on real (private, proxied) results." },
        { emoji: "📲", time: "00:05", title: "Install 51 Mimi Games as a real app — straight from the browser", desc: "The hub is now installable: on a supported browser (Chrome, Edge, and most others), visiting the site offers a genuine \"Install app\" option — no download, no separate file, just a button in the browser's own UI. Installing gives it its own icon on your desktop/home screen and its own window, no address bar or tabs. It also works offline once you've opened it — the service worker quietly caches whatever you've loaded (the hub itself, and any game you've actually played) so reopening it without a connection still works, while anything live — signing in, the private page viewer, multiplayer — still always talks to the real server, never a stale cached copy. Confirmed installable via Chrome's own installability check (zero errors) and confirmed working fully offline: closed the network entirely, reloaded, and the hub still opened and let me browse into a game." },
        { emoji: "⌨️", time: "00:04", title: "The on-screen gamepad keyboard now works inside the private page viewer too", desc: "Since the search-home page viewer's frame got gamepad-cursor support, the last missing piece was typing — the hub's on-screen keyboard (pops up automatically for gamepad players focusing any text box) was only ever wired to the hub's own page, not the separate document living inside that viewer's iframe, so a text field on a privately-fetched page couldn't be typed into with a controller at all. Turned up a real, subtler bug fixing it: with the keyboard now watching two documents, moving focus from the hub into a text field inside the iframe made the HUB's own side think focus had left a text field entirely (its own view only sees the <iframe> tag, not what's focused inside it) and closed the keyboard a beat after it correctly opened. Fixed by having that check look inside a focused iframe for what's actually focused there, rather than stopping at the iframe's own edge — confirmed by actually typing through the on-screen keyboard into a real form field on a fetched page." },
        { emoji: "🏎️", time: "00:03", title: "Kart Circuit 3D: rebuilt on a real 3D engine (Three.js/WebGL) instead of hand-rolled fake-3D", desc: "After several rounds of fixes to the old 3D view this session, it still wasn't holding up — because the whole thing was a hand-rolled illusion: every road strip, kart, coin, and ramp was a flat 2D shape on a plain canvas, individually math'd into looking 3D-ish through manual perspective formulas, with no real geometry, camera, or depth buffer underneath any of it. That's fundamentally fragile — every fix this session was patching one more edge case in that illusion rather than the underlying shape of the problem. Replaced it with an actual WebGL 3D scene: real road geometry, real kart models (with wheels, a chassis, and the dark outline from an earlier fix — now genuine 3D silhouette, not a 2D hack), real ramps/boost pads/loops (an actual ring shape now, not a fake billboard), item boxes, coins, and a checkpoint marker, all lit by real directional/ambient lighting instead of flat fills, viewed through an actual perspective camera instead of manually-computed screen positions — with a real depth buffer, so nothing can 'vanish' or warp at close range the way the old renderer's manual math kept doing. The existing camera smoothing (all 4 modes — Chase/Hood/Wide/Outside) is untouched under the hood; only what it's used to aim was replaced. A proper skybox now too — the same mountain-silhouette art the old renderer drew fresh every frame is baked once into a texture and wrapped around the scene, so it turns with the camera with no per-frame cost. Verified across 5 maps (including a 24-racer World map), all 4 camera modes, 2/3/4-way split-screen, a live wireless multiplayer session, and gamepad cursor control, all with zero console errors and a clean 80-game hub sweep. The old renderer stays in the code on purpose, as an automatic fallback for any browser/device with no WebGL — nobody loses the ability to play." },
        { emoji: "🎮", time: "00:02", title: "The private page viewer now works with a gamepad — including clicking links", desc: "The search-home page viewer's frame had no allow-same-origin, so the hub's own gamepad cursor (which reaches inside frames by reading their DOM directly) couldn't see anything inside it at all — the whole viewer was just one big dead zone, cursor or not. Turned that on (still no allow-scripts — nothing fetched ever runs code, this only lets the hub's own trusted script look at the page, the same access it already had into Kart Circuit's frame). That exposed a second problem once links became reachable: a plain click on one would either navigate the frame straight to the real site directly (breaking the whole \"your browser never contacts it\" point of this feature) or, for a relative link, resolve against nothing and fail, since a privately-fetched page has no real URL of its own to resolve against. Every link click — gamepad or mouse — is now caught first, resolved against the page's actual URL, and sent back through the same private fetch instead, so browsing from page to page stays exactly as private as the first page you typed in. Confirmed by actually driving the cursor with a simulated controller onto a real link and clicking it." },
        { emoji: "🔎", time: "00:01", title: "A new front page: a real search-engine-style home screen, with 51 Mimi Games as an app", desc: "The hub no longer opens straight into the game picker — it opens on a search-engine-style home page instead (a search bar, and an Apps row below it with a single 51 Mimi Games tile for now). Tap the tile to go straight into the existing hub exactly as it worked before. The top task bar reflects this: on the new search-home screen it's stripped down to just 🎵 Music, ⚙️ Settings, and 👤 Profile — no hub branding, browse controls, or What's New/Play Together — so it reads like an actual search homescreen rather than an app's chrome. Step into 51 Mimi Games and the full task bar is back, completely unchanged. Typing something and hitting Search doesn't send you to Google or any other outside search engine — the server fetches that exact page itself and shows it to you right there (private, URL-in/page-out, not keyword search), and it flat-out refuses to fetch anything on this server's own private network (localhost, 10.x/172.16.x/192.168.x, link-local, etc.), including re-checking that on every redirect a page makes, so it can't be pointed back at itself or anything else on the local network." },
      ],
    },
    {
      date: "2026-08-09",
      entries: [
        { emoji: "🔫", time: "00:09", title: "Gun Game Arena: real loadouts, 3 maps, and health packs — a proper team deathmatch now", desc: "The old \"every kill auto-upgrades your one gun, land a Knife kill to win\" ladder is gone, replaced with a real loadout system: pick a Primary in the lobby (better ones unlock as you rack up match wins — SMG is always available, Shotgun/Rifle/Sniper unlock at 3/6/10 wins), Secondary (Pistol) and Melee (Knife) are always available, and you keep that same loadout for the whole match — switch between all three anytime with 1/2/3 (LB/RB on a gamepad, the new 🔄 button on touch). Winning is now first team to 30 kills, tracked live in the HUD and synced across every player in a room. Health pack pickups (glowing green crosses) are scattered around every map and heal you when you're hurt — there was previously no way to recover HP except dying. And there are 3 maps to choose from in the lobby now instead of just one: Crossfire (the original layout), Twin Towers (open flanking lanes, favors long-range weapons), and The Maze (tight symmetric corridors, favors close-range weapons)." },
        { emoji: "🐛", time: "00:08", title: "Kart Circuit: racer karts now have a dark outline, so no color gets lost", desc: "Reported as \"the red kart is invisible,\" and it checked out: a kart's color is the ONLY thing telling it apart from the road/curbs/sky behind it — no outline, nothing else — so a racer whose assigned color happens to be a close hue match for a busy background (a warm red kart against Neon Loop's magenta-saturated curbs and neon skyline, specifically) could genuinely disappear into it at a glance, even though the color itself was rendering correctly the whole time (checked the actual pixel values to confirm). Added a thin dark outline around every kart — the 3D view, the mini-map dot, and the top-down 2D mode — so every racer stays legible against any map's palette, not just the ones their assigned color happens to contrast with." },
        { emoji: "🐛", time: "00:07", title: "Kart Circuit 3D: the road forking into two strips on Neon Loop and 5 other maps — found the real cause", desc: "This turned out not to be a geometry bug at all, and the two previous fixes today were both real but neither one addressed it. Sampled the actual rendered pixels between the two \"strips\": the color there wasn't background, it was the road surface — just rendered dark enough that it blended into the equally-dark background right next to it, with only the bright neon curb stripes on each edge standing out. The road was never missing or forking; it just wasn't visible enough to read as connected pavement, so two bright lines with barely-visible fill between them looked exactly like a fork. Six maps had this — Neon Loop (the default map) was the worst hit, followed by Grove Circuit, which had almost no brightness difference between road and grass at all. Brightened the road/shoulder colors on all six, same hues, checked against every other map's palette to confirm nothing else was this close to invisible." },
        { emoji: "🐛", time: "00:06", title: "Kart Circuit 3D: the actual road surface was warping too — this was the big one", desc: "The last two fixes covered coins/items/hazards and boost pads/ramps, but missed the most visible piece: the road itself. Every strip of track is drawn from 4 points spanning its width (both shoulders, both edges), each of which was projecting with its own independently-computed size — up close, especially on the tighter default Cup tracks (Neon Loop and the 7 others), that let the two sides of the road diverge by up to 3x in size from each other, shredding the track surface into a warped, rippled mess right around the kart. This was likely the dominant cause of the reported \"3D mode is broken\" look, more than the smaller decal issues — the earlier fixes were real but only addressed part of it. Same fix as the others: every point across a given strip of road now shares one size instead of computing its own. Checked on all 14 maps (8 Cup + 6 World) — clean everywhere now, including the default map most players see first." },
        { emoji: "🪙", time: "00:05", title: "Coin Flip Duel: now shows what was actually called, plus a flip history", desc: "Checked the actual randomness live (200+ simulated rounds): both the coin flip and the CPU's guess are genuinely fair 50/50 draws, no bias either direction. But the game never told you what the caller had called — only whether they won — so with a caller only getting about 3 calls in a best-of-7 match, an ordinary short streak (in one of my own test runs it landed the same side 4 times in a row, ~6% odds) is very easy to misread as rigged with nothing to check it against. Every round's message now names the actual call (\"CPU called Heads — guessed wrong\"), and a running \"Recent flips\" strip (last 16, with a live H/T tally) sticks around across the whole session so you can see the real balance for yourself instead of having to trust it." },
        { emoji: "🐛", time: "00:04", title: "Kart Circuit 3D: fixed warped, spiky-looking boost pads and ramps up close", desc: "Another real regression from the same coin/boost-pad position fix. Boost pads and ramps are drawn as flat multi-corner shapes (a chevron, a quad) — each corner was being projected with its own independently-computed distance-based size, and up close those sizes could diverge sharply corner to corner (just a few world units apart), warping what should be a clean rectangle or chevron into a spiky, distorted shape — screenshotted by a player as looking like a stray glowing hand on the road. Every corner of a given decal now shares one size, computed once from the decal's own center, while each corner still gets its own screen position — so it still skews correctly with viewing angle, it just doesn't balloon unevenly anymore. Checked up close against real boost pads and ramps on multiple maps after the fix; clean in every case." },
        { emoji: "🐛", time: "00:03", title: "Kart Circuit 3D: fixed ghost coins/item boxes/hazards appearing behind you", desc: "A real regression from yesterday's coin/boost-pad position fix. Coins, item boxes, and hazards were switched to a projection function that deliberately never hides anything (that's what stops a close-up decal from vanishing mid-turn) — but nothing was then filtering out points that are actually behind the camera, so ones on the far side of the track, or ones you'd just driven past, could land back inside the visible screen area and show up as stray icons floating where they shouldn't be. Added the same \"well behind and not just close\" exclusion the boost pad/ramp/loop renderers already used. Verified clean across all 6 maps." },
        { emoji: "🎯", time: "00:02", title: "Gamepad cursor: a new Select mode, alongside Mouse mode", desc: "⚙️ Settings → Gamepad now has a Mode switch. Mouse (the original, still the default) moves the cursor smoothly wherever the stick points, like a real mouse. Select is different: the stick doesn't glide the cursor at all — tilt it toward the button or tile you want and the cursor jumps straight there immediately, snapping between selectable things instead of drifting across the screen between them. Same click button either way to activate whatever's currently selected. Meant for anyone who finds fine analog aiming fiddly — Select trades precision-under-drift for \"exactly one thing is highlighted at all times, and one tilt gets you to the next one.\"" },
        { emoji: "📸", time: "00:01", title: "Profile pictures — and they show up as your camera in Kart Circuit", desc: "👤 Profile now has a picture: pick any photo and it's auto-cropped and shrunk to a small square before it ever leaves your browser. Host or join a wireless Kart Circuit race and it shows up in the camera strip exactly like a live video tile would — no webcam needed, no one has to turn on video chat for you to see who's racing. Actually turn video chat on and your live feed simply takes over that same spot. No picture yet and no camera either? You still get a tile, just a plain colored circle with your initial, so the strip always shows everyone who's connected." },
        { emoji: "👋", time: "00:01", title: "An actual departure animation when someone leaves a Kart Circuit race", desc: "Their camera tile used to just vanish the instant they disconnected. Now it pops, shrinks, and slides off before it's removed. There's also a new on-track moment for it: a fading \"👋 Name left\" label with a little poof of particles appears right where their kart was the moment they dropped — their kart itself doesn't disappear (it smoothly switches to AI control so the race keeps going), but the moment they actually left is now something you'd notice mid-race, not just a line in the chat log." },
      ],
    },
    {
      date: "2026-08-08",
      entries: [
        { emoji: "🙋", time: "23:59", title: "Sign in as one of up to 10 remembered accounts, or just play as a Guest", desc: "Open 👤 Profile on a device a few people share and you'd have to retype your name every time to sign in. Now the sign-in screen shows a one-tap chip for every account that's signed in on that device before (up to 10, most recent tracked) — tap yours, enter your password, done. Signing out drops you straight back on that picker instead of a blank form. Didn't want to make an account at all? Hit \"🙋 Continue as Guest\" — this was already how the hub worked without signing in (every game still saves its own high scores locally either way), just made into an explicit, visible choice instead of something you'd only find by ignoring the panel." },
        { emoji: "🏀", time: "23:59", title: "A genuinely better Basketball Shoot", desc: "The hoop was a flat trigger zone before — shots either scored or silently vanished. Now the rim posts, backboard, and floor are real collision surfaces: a near-miss visibly rattles off the rim or banks off the backboard instead of just disappearing, and a short shot bounces on the floor before it's called a miss. Chain makes in a row for a combo bonus (+1 at a 3-streak, +2 at 6+), and a clean swish — straight through with no rim or backboard contact — scores an extra point, both called out on screen. Score 10+ in a round and the hoop itself starts gently swaying side to side for a late-game challenge. The ball now visibly spins in flight with a fading shot trail behind it, and the net flexes on a make." },
        { emoji: "🏁", time: "23:59", title: "Kart Circuit: coins and boost pads now line up between the 3D view and the mini-map", desc: "Real bug: on a curve, the 3D camera's view direction lags slightly behind the true bearing to a nearby pickup, and the math used to project coins onto the screen used that lagged direction as its \"distance\" — so a coin could render as if it were nearly on top of you well before you'd actually reached it (matching the mini-map, which is always accurate). Boost pads had a related but different problem: an earlier fix stopped them from vanishing on turns by flooring their apparent distance at half of the true distance, which fixed the vanishing but then made them read as roughly twice as close as they really were — the same visual mismatch, for a different reason. Coins, item boxes, hazards, and thrown items now all project using true straight-line distance from the camera, the same measure the mini-map and the actual world-space pickup trigger already used, so what you see lines up with where the pickup really is." },
        { emoji: "🔐", time: "23:59", title: "Passkeys, a recovery code, and an optional recovery email", desc: "👤 Profile → Security has three new ways to secure or recover your account. Passkeys use your device's own Face ID/Windows Hello/fingerprint/security key — that check happens entirely on your device, this hub never sees or stores anything biometric, only a public key, exactly like any other site with a \"Sign in with a passkey\" option. Once added, sign in with just a name and a tap/glance instead of a password. A one-time recovery code is the real fix for a forgotten password (this hub has no mail server to send a reset link with) — generate one, save it somewhere safe, and it can set a new password once before it needs regenerating. A recovery email field is there too, but it's reference-only for the same reason — nothing here can actually send mail." },
        { emoji: "🔄", time: "23:59", title: "Profile sync now covers a lot more", desc: "Signing into a 👤 Profile backs up and restores your settings from any device on the network — that used to mean just gamepad/Kart Circuit prefs. Now it also covers your hub theme (including a custom one's exact colors), music on/off, favorites, continue-playing history, and every game's high scores and bests. Signing in applies your theme immediately, no reload needed." },
        { emoji: "🎨", time: "23:59", title: "6 more theme presets, plus a fully custom one", desc: "⚙️ Settings → Theme now has 8 choices total: Dark, Light, Midnight Purple, Ocean, Sunset, Forest, High Contrast — and Custom, which is genuinely custom: pick your own background, panel, two accent colors, and text color with color pickers, live-previewed as you pick. Every preset (and your custom one) is just a handful of CSS variables under the hood, so it reaches the same buttons/borders/panels/text the Light theme already did — an individual game's own canvas art (Bike Rush's sky, a chess board's squares, etc.) stays as its own designed look either way, same as before." },
        { emoji: "☀️", time: "23:59", title: "A white theme, in ⚙️ Settings", desc: "A real light theme, not just a filter — white background, no more animated dark gradient or glow blobs, tiles get light panels with dark text, and the LED strip around each game icon (a dark-console-shelf effect that read as pure noise on white) is switched off entirely. Toggle it under ⚙️ Settings → Theme; it's saved and stays picked next time you visit. This reskins the hub's own chrome — the menu, panels, buttons — not how any individual game renders inside its own canvas." },
        { emoji: "🐛", time: "23:59", title: "Game tile titles were rendering black this whole time", desc: "Not a brightness/contrast tweak — a real bug. Game tiles are <button> elements, and buttons don't inherit page text color from the browser's default styling the way a <div> would; they get their own default (usually black). The tile title text never set an explicit color of its own, so it silently fell back to that default and rendered black-on-dark the entire time, completely unaffected by any of the --text-dim adjustments today because it was never using that variable in the first place. Now explicitly colored, correctly, on the tile itself." },
        { emoji: "🔆", time: "23:59", title: "Text brightness, take two", desc: "One brightness pass wasn't enough — pushed --text-dim (category labels, hints, captions) much closer to white this time." },
        { emoji: "🖥️", time: "23:59", title: "Games are bigger by default now, not just in Fullscreen", desc: "Every canvas-based game used to cap itself fairly small so it would always fit on screen without scrolling. Turns out that traded away too much — the game is the whole point of opening one, so it should dominate the view close to how Kart Circuit already looks, even before touching Fullscreen. Games are much bigger now; a few of the largest (Pinball, Coast Guard, Snake, and Kart Circuit itself) go back to needing a bit of scroll to see everything below the canvas, the same trade already accepted for Kart Circuit." },
        { emoji: "🐛", time: "23:59", title: "Fullscreen: fixed a real \"squashed in the corner\" bug (Firefox)", desc: "Every game with a Fullscreen button centers its canvas using a CSS rule keyed off the :fullscreen pseudo-class. Turns out that's unreliable across browsers: in Firefox specifically, the canvas's own element genuinely matched :fullscreen (confirmed directly), yet the stylesheet rules written against that selector silently never applied — not even unrelated ones — so the centering never happened and the canvas sat pinned in the top-left corner of an otherwise black screen. Switched every game's Fullscreen handling to toggle a plain CSS class instead of depending on the pseudo-class in the stylesheet, which sidesteps the whole issue. Confirmed fixed in both Chromium and Firefox." },
        { emoji: "🏎️", time: "23:59", title: "Kart Circuit: AI racers could never finish a single lap", desc: "A real, serious bug: every AI-controlled racer's steering aims at a point a fixed distance ahead of itself along the track — but that distance was large enough (over half the gap between two checkpoints) that it cut corners hard enough to miss a checkpoint's 48-unit trigger radius entirely, on every single lap, forever. Confirmed live: with the bug, three AI racers drove for over a minute (multiple full laps' worth of track progress) without a single one advancing past checkpoint 1 of 6 — meaning no CPU racer could ever legitimately finish a race. Their look-ahead distance is scaled down to a sane fraction of a checkpoint gap; all three racers now complete full laps cleanly within about 50 seconds." },
        { emoji: "🎁", time: "23:59", title: "Kart Circuit: driving over an item box while already holding one silently swapped it away", desc: "Rolling over an active item box always handed you a brand-new random item — even if you were already holding one you hadn't used yet, in which case your existing item just got silently discarded and replaced (and the box was wasted for everyone else on the track, since it went on cooldown regardless). Now a racer already holding an item just drives through the box untouched; it stays active for someone who can actually use it." },
        { emoji: "🎮", time: "23:59", title: "9 new 3D games (80 games now!)", desc: "All pseudo-3D, all built on the same road-projection tech as Bike Rush and Ski Slalom, each with a genuinely different hook: 🚀 Space Runner (dodge an asteroid field, grab gems), 🧟 Zombie Highway (coast into a car and crash, but ram one at speed and you smash right through for a bonus), 🦁 Jungle Safari (dodge trail hazards and snap timed photos of wildlife), 🛹 Skate Park (ollie over obstacles for trick points instead of just dodging them), 🤿 Deep Sea Dive (an oxygen meter you have to manage with air bubbles), 🦅 Canyon Flight (dodge in two directions at once — lane AND altitude), 🏜️ Dune Buggy Rally (a desert checkpoint time trial with dune jumps), 🛷 Bobsled Run (icy chute walls and patches that make your steering twitchy), and 🪂 Sky Dive (freefall, dodge birds, land as close to the target as you can). Find them under Action and Sports." },
        { emoji: "🔆", time: "23:59", title: "Slightly brighter secondary text across the hub", desc: "Category labels, hints, and other dimmed text (the --text-dim color used everywhere from game tiles to panel captions) were a little low-contrast against the dark background — nudged brighter for easier reading." },
        { emoji: "↔️", time: "23:59", title: "Game grid: no more black bars down the sides on wide screens", desc: "The grid was capped at 1400px wide and centered, which looks fine on a laptop but leaves two big blocks of empty black space on anything wider (a 1920px-wide window had 260px of dead space on each side). The cap's gone — the grid now genuinely uses the full width of the window, fitting more columns per row as the window gets wider instead of just growing the margins around a fixed-size block." },
        { emoji: "🧩", time: "23:59", title: "Game grid: no more empty gap at the end of the last row", desc: "71 doesn't divide evenly into a row of 8, so the grid's last row (Table Tennis through Yahtzee) always left one empty, unfilled slot of black space next to it — a side effect of how CSS grid reserves a full row of tracks whether or not there's a tile for each one. Switched the grid to flexbox instead, which has no such reserved track: a partial last row's own tiles now stretch to evenly fill the leftover width instead of leaving a gap next to them. Same for any filtered/searched view with a partial last row." },
        { emoji: "🔲", time: "23:59", title: "Game grid: back to normal-sized icons", desc: "Briefly tried shrinking every tile down small enough that all 71 games would fit on one screen with no scrolling at all — readable, but noticeably smaller than before, and not the trade worth making. The grid is back to its normal tile size (full category text, full-size icons); browsing scrolls through the library like any app grid does. The \"fits without scrolling\" work stays exactly where it matters — inside an individual game screen once you've opened one." },
        { emoji: "🖥️", time: "23:59", title: "Fullscreen was broken, and almost every game now fits the screen with zero scrolling", desc: "Real regression from the last \"fit the screen\" pass: the new canvas height cap didn't get out of the way when a game actually went fullscreen, so Bike Rush/Coast Guard/Gun Game Arena/Ski Slalom's Fullscreen button filled the whole window's width but squashed the game into a thin letterboxed strip — fixed, fullscreen now genuinely fills the screen again. While in there, went much further on the original ask: audited all 71 games individually instead of just the canvas-heavy ones, and shrank oversized on-screen D-pads, puzzle grids (Sudoku, 2048, Word Guess, Maze Runner, Block Drop), and two games with their own stale, oversized canvas caps (Air Hockey, Bubble Shooter) left over from before the shared cap existed. Kart Circuit's embedded frame also switched from a flat \"82% of viewport height\" guess to actually accounting for the surrounding chrome. Result: every game fits at common laptop/desktop sizes (1366×768 and up) with no scrolling at all; only unusually short windows (well under 700px tall) still need a little." },
        { emoji: "💡", time: "23:59", title: "An LED strip around every game icon", desc: "Every tile in the grid now has a thin red-to-blue LED strip traced around its whole outline — a slow shimmer at rest, a brighter glow on hover — matching the console-style redesign from earlier today." },
        { emoji: "📐", time: "23:59", title: "A lot more of the hub now fits on one screen without scrolling", desc: "Several real layout bugs, not just one: the landing screen assumed the topbar was always exactly 68px tall, so it scrolled past the bottom of the page the moment the topbar wrapped to more than one row (which is most of the time). Every canvas-based game rendered at its full native resolution with no height cap, so a tall canvas (Bike Rush, Coast Guard, Asteroids, and now Ski Slalom) just pushed everything below it off-screen. The search/filter/Surprise Me row stayed visible in the topbar even while a game was open, even though it does nothing there. And the persistent \"how to play\" text block under every game duplicated the dedicated How to Play button's animated guide while permanently taking up 100+ pixels. All four are fixed: the layout now actually flexes to fit the real topbar height, canvases cap themselves to a sane share of the viewport, the search row only shows up when you're actually browsing, and the controls/tips text collapses behind a one-line \"Controls & tips\" toggle. Most games now fit the screen exactly with zero scrolling; a couple of the biggest ones (Kart Circuit, Pinball) still need a little, by design." },
        { emoji: "⛷️", time: "23:59", title: "New game: Ski Slalom 3D (71 games now!)", desc: "A pseudo-3D downhill time trial, built on the same road-projection tech as Bike Rush but a genuinely different game: carve left/right through a fixed slalom course of red/blue gate poles (clean gates shave time off your run, missed ones add a penalty), dodge trees and rocks (a wipeout costs time but doesn't end the run), and catch ramps for real airtime — the skier visibly lifts off the slope with a shrinking shadow underneath, landing back down after a beat. Race to the finish banner as fast as you can; your best time is saved. Find it under Sports." },
        { emoji: "♠️", time: "23:59", title: "Blackjack couldn't load at all", desc: "A real crash-on-open bug: the very first render, before you've even clicked Deal, tried to show the dealer's total for an empty hand — reading the value off a card that didn't exist yet, which threw immediately and took the whole game down with \"This game hit an error and couldn't load.\" Fixed to leave the dealer's total blank until there's an actual hand to show." },
        { emoji: "🆕", time: "23:59", title: "What's New: a Get Updates button", desc: "Since this hub is a static site, \"checking for updates\" just means reloading so the browser picks up whatever the server currently has — that's now one click via 🔄 Get Updates in the What's New panel, instead of remembering to hit refresh yourself." },
        { emoji: "🏍️", time: "23:59", title: "Bike Rush looked flat/broken before you hit Start", desc: "The idle screen — before clicking Start Ride — only drew the sky and a solid black rectangle for the road area, no perspective at all, so the game looked like a plain 2D gradient rather than the pseudo-3D highway it actually is. It now shows a real (dimmed) preview of the road, scenery, and bike behind the Start button, same as it looks once you're actually riding." },
        { emoji: "🎮", time: "23:59", title: "A real front screen: Play Solo, Play Multiplayer, or Play Wireless", desc: "Opening the hub used to drop you straight into the full 70-game grid. Now there's a front screen first, three big choices: Play Solo (the whole grid, same as before), Play Multiplayer (the grid pre-filtered to 👥 Multiplayer games), and the new 📡 Play Wireless (opens the same host-or-join room panel as the 📡 Play Together button, for playing with someone else's device over the network). Search, category filters, and Surprise Me only make sense once you're actually browsing, so they're tucked away until you pick Play Solo or Play Multiplayer — Music/Settings/What's New/Profile/Admin stay reachable from the top the whole time. The logo doubles as a Home button back to this screen, and Escape backs out one step at a time same as everywhere else in the hub." },
        { emoji: "🕹️", time: "23:57", title: "Hub redesign: styled after a certain handheld console", desc: "New color scheme — Joy-Con-style neon red and blue as the two accent colors, a near-black console-dark background instead of the old purple tint, rounder app-icon-style game tiles, and a red-to-blue gradient line under the topbar. No logos or trademarks used, still not affiliated with Nintendo (see the footer) — just an aesthetic nod." },
        { emoji: "👤", time: "23:55", title: "Local players moved into the 👤 Profile panel, where they belong", desc: "The last two entries had local-player sign-in split across the Play Together panel and Kart Circuit itself — two different places to do the same thing, and Kart Circuit had no business owning a sign-in form. It's now all in one place: open 👤 Profile → Local players to sign in or sign up up to 4 people on this device. Local Party and Kart Circuit (split-screen seats and the \"Playing as\" solo picker) both just read that same roster automatically — nothing to set up in either one. Also fixed: with this section added, the Profile panel could run taller than its card and spill past the edge of the screen on a shorter window; it now scrolls inside the card like the other panels instead." },
        { emoji: "🏎️", time: "23:40", title: "Kart Circuit: sign in up to 4 players, switch who's driving solo, sign up right there", desc: "The local multiplayer panel now has its own roster: up to 4 people on this PC can each sign in with their profile (or Sign Up for a brand-new one on the spot — no need to leave Kart Circuit for the hub's Profile button). Split-screen seats P1-P4 automatically use whoever's signed into that slot. Playing solo? A new \"Playing as\" selector lets you pick which signed-in player is actually driving, so four people can each sign in once and take turns without re-entering a password every time — or just leave it on Guest and race as your selected character, same as before. Names you've used here are remembered on this device (up to 10) so returning players get an autocomplete instead of retyping — the password still has to be the real one, that part's never skipped." },
        { emoji: "👥", time: "23:05", title: "Sign in multiple profiles for local multiplayer", desc: "Local Party (take turns on one keyboard, in any game) used to label everyone \"P1\"/\"P2\"/etc. — fine for a quick pickup game, but if the people actually playing have their own profiles, there was no way to show that. The Play Together panel's Local Party section now has a 👤 Sign in players instead option: pick 2-4 players, and each one can type their name and password to sign in and show their real name (and 🛠️ badge, if they're a dev) on the scoreboard — or just type a name with no password to play as a plain guest, no account needed. Signing a second/third/fourth player in here is separate from the one real \"signed in\" session behind the 👤 Profile button — it only checks a name+password against that profile, it never takes over your gamepad or Kart Circuit settings." },
        { emoji: "🔫", time: "22:35", title: "Gun Game Arena: you could join the same room over and over as a ghost copy of yourself", desc: "Nothing stopped Join Room (or Host Room) from being clicked again after you were already in — each click opened a brand-new connection to the server without ever closing the last one, and the server had no way to know it was the same person, so it just added another duplicate entry to the room every time. Fixed two ways: Join Room and Host Room now refuse to do anything while already connected, and both buttons (plus the room code field) hide the moment you're in a room — Leave Room is the only way back to them. Verified with two real browser sessions: joining now shows exactly one entry for the joining player, no matter how many times the button gets hit." },
        { emoji: "🎮", time: "22:10", title: "Bike Rush (and Block Drop's/Pinball's D-pad) went completely dead on gamepad", desc: "A real bug in today's earlier gamepad work: hiding the controller cursor while a game is being actively played accidentally also stopped the hub's D-pad-to-arrow-keys bridge from sending anything at all — for most games that didn't matter since they read the gamepad directly themselves, but Bike Rush has no gamepad code of its own; it's driven entirely by that bridge, so the D-pad went dead the instant a ride started. Block Drop's move/rotate and Pinball's flippers (both still D-pad-driven even though their extra button, like hard drop or launch, is handled natively) had the exact same problem. Fixed at the source: hiding the cursor no longer stops the D-pad or Back-to-Grid from working underneath it." },
        { emoji: "🏓", time: "21:45", title: "Table Tennis: totally dead to gamepad (and Up/Down arrows)", desc: "Went looking for \"gamepad does nothing in some games\" and found a real one: Table Tennis only ever listened for W and S — not the Up/Down arrow keys at all, which is what the hub's controller D-pad actually sends. Keyboard players hitting the arrow keys out of habit had exactly the same problem. Fixed by accepting Up/Down as the same input as W/S, so both the arrow keys and a gamepad's D-pad now move the paddle. Audited every other keyboard-controlled game in the hub for the same gap — nothing else was missing arrow-key coverage." },
        { emoji: "🕹️", time: "21:20", title: "Kart Circuit: pick who's Player 1 when two controllers are connected", desc: "With two people each holding their own controller, which one landed on which seat used to just be whatever order the browser happened to report them in — not a real choice. Now, the moment the setup screen sees two or more controllers already connected, it asks right there at the top: pick a name and that controller becomes P1, or dismiss it and decide later from the gamepad panel further down (every connected controller has its own \"Make P1\" button there too). The choice sticks by the controller's own identity, so it survives a reconnect." },
        { emoji: "⚙️", time: "20:40", title: "A real Settings button, and the controller cursor's hover animations finally match a real mouse", desc: "Gamepad settings (Click / Back to Grid / Unlock Cursor remapping, pointer size/speed) had been living inside the Play Together panel, which made no sense if you just wanted to remap a button. They now live behind a dedicated ⚙️ Settings button in the topbar. Separately: the controller cursor could never trigger real CSS :hover — no browser allows that for synthetic input — so hovering a game tile with a controller just showed a plain outline instead of the tile's actual glow-ring/lift animation, same gap on buttons, chips, and cards everywhere else in the hub. Every one of those now gets its real hover animation from a controller too, not just a mouse." },
        { emoji: "🎮", time: "19:30", title: "Gamepad: more games support it, and the cursor finally gets out of the way", desc: "Asteroids, Pinball, Block Drop, and Sprint Race all gained real controller actions (Fire, Launch, Hard Drop, Mash) on top of the D-pad movement they already had — every game with its own gamepad support now covers 8 titles total. Bigger fix: the hub's controller cursor used to keep drifting across the screen on top of active gameplay in all of them except Kart Circuit, because only Kart Circuit had a way to tell it to get out of the way. Every game that reads the controller directly now hides it automatically while you're actually playing — and a new Unlock Cursor button brings it back instantly if you need a menu or setting mid-game, no unplugging required. Click, Back to Grid, and Unlock Cursor are all individually remappable with a live \"press a button\" capture, the same button-naming and one-click-reset experience Kart Circuit's own gamepad settings already had." },
        { emoji: "🏍️", time: "18:50", title: "Bike Rush: engine sound and traffic music", desc: "The bike now has a real engine note that pitches up as you speed up — it's moving, so it makes noise. Traffic does too: the nearest car's engine grows louder the closer it gets. And every car you pass rings its lane's own note as it goes by (a simple C-major triad, one note per lane), so a good run through traffic turns into a loose little melody on top of the engine noise." },
        { emoji: "🧹", time: "18:30", title: "Clear button for Continue Playing", desc: "A small Clear button next to the Continue Playing heading wipes your recently-played history and hides the row, for whenever you'd rather it start fresh." },
        { emoji: "🕶️", time: "17:40", title: "New filters: 🕶️ 3D and 👥 Multiplayer", desc: "Two new chips next to the categories, alongside All and Favorites. 🕶️ 3D instantly finds every pseudo-3D game in the hub (Bike Rush, Coast Guard, Gun Game Arena, Kart Circuit); 👥 Multiplayer finds every game that supports more than one player, across every category." },
        { emoji: "🏍️", time: "17:00", title: "New game: Bike Rush (70 games now!)", desc: "A pseudo-3D highway dash. Hold the throttle and your score climbs fast — coast along slow and you'll barely earn anything (a \"Too Slow!\" warning tells you when). Weave between three lanes of oncoming traffic to survive; clip a car and you'll spin out, losing speed and a life, with a moment of flashing invulnerability to recover. Sneak past a car in the next lane over for a near-miss bonus. Three crashes ends the run. Touch controls included. Find it under Action." },
        { emoji: "🏁", time: "16:10", title: "Kart Circuit: the road could vanish entirely on tight corners, and Auto Steer could spin you out", desc: "Two related bugs on Neon Loop (and any other tight, few-checkpoint track). The 3D road renderer rejected any edge point that dipped behind the camera's near plane — fine most of the time, but on a sharp bend it could reject every point right where you're standing, leaving the kart floating over blank grass with zero road drawn (confirmed live: the mini-map showed you correctly on the track the whole time). Fixed the same way close-up decals were fixed earlier — clamp instead of reject, so the near part of the road always draws. Separately, Auto Steer aimed straight at the next raw checkpoint gate (as few as 6 for a whole loop) instead of the curve just ahead, which could yank the wheel hard enough to spin the kart out at a tight corner — now it aims at a point a short distance ahead on the actual road, the same way the AI racers already steer." },
        { emoji: "🎨", time: "14:30", title: "The hub itself got a full redesign, with animation everywhere", desc: "A ground-up visual pass on the main menu: an animated gradient backdrop with slow-drifting glow blobs, a frosted-glass topbar with a shimmering gradient logo, game tiles that fade/slide in staggered on load and get a spinning glow ring on hover, a satisfying pop on the favorite star, and a smooth fade between the menu and a game instead of an instant cut. Nothing about how any individual game works changed — this is the shell around all 69 of them." },
        { emoji: "⭐", time: "13:15", title: "Favorites, Continue Playing, Surprise Me, and background music", desc: "Star any game to pin it under a new ⭐ Favorites filter. A Continue Playing row now sits above the grid with your recent games, the last one played highlighted as \"Jump back in.\" A new 🎲 Surprise Me button picks a random game from whatever you're currently browsing. And there's now genuinely optional background music for the menu (🎵 Music button, off by default, its own little chiptune loop) that automatically pauses the moment you open a game — each game keeps its own sound as before. Search also now matches category, not just title, so \"cards\" finds every card game." },
      ],
    },
    {
      date: "2026-08-02",
      entries: [
        { emoji: "🗺️", time: "15:20", title: "Coast Guard: start with passengers, find more on islands, and a real nautical map", desc: "You now launch with a couple of survivors already aboard. New survivors show up two ways — floating in open water like before, or waiting on the shore of one of the scattered islands. A proper map now sits in the top-right at all times: every island, the storm, an incoming tsunami's wavefront, and your boat's heading — plus a dashed line and label pointing at whatever actually matters right now (the nearest survivor, or the home dock once you're carrying anyone and it's time to bank the save)." },
        { emoji: "🏝️", time: "13:50", title: "Coast Guard: islands, real boat physics, and tsunamis", desc: "A big update to the rescue game. Islands are now scattered around the map — one of them is home base, flagged and flanked by palm trees, with the dock at its shore; the rest double as safe high ground. Rescued survivors now visibly ride along in the boat instead of just being a number. The boat has real momentum now — turning hard at speed genuinely drifts/slides instead of instantly pivoting to face the new heading, the way a boat actually handles on water. And watch for tsunami warnings: a wave sweeps across the entire map, and anyone caught in open water (you or a stranded survivor) takes it hard — but riding it out on an island keeps you safe." },
        { emoji: "🖥️", time: "12:40", title: "Gun Game Arena & Coast Guard: Fullscreen actually fills the screen now, and stuff stops disappearing/reappearing wrong", desc: "Two real bugs. Fullscreen: the browser correctly went fullscreen, but nothing told the canvas inside to actually grow to fill it — it just sat tiny in a corner of an otherwise black screen. It now scales up properly, aspect ratio preserved. Rendering: objects behind the camera (Coast Guard's dock, Kart Circuit's ramps/pads/loops/hazard drones) had no way to actually disappear — they'd stay visible on screen no matter which way you turned, since the projection math was deliberately built to never fully reject a point (that's what keeps close decals from vanishing right as you reach them). Added a proper behind-camera check that only culls things that are BOTH facing away AND genuinely far off — verified it doesn't undo the original close-up fix (re-ran the full 6-map audit from when that was built: zero failures)." },
        { emoji: "🔑", time: "11:05", title: "Profiles: change your own password, and a scrollable Admin list", desc: "The signed-in profile panel now has a Change Password button — enter your current password plus a new one, no admin needed. Also fixed the Admin panel added earlier today: the profile list was cut off with no way to scroll down to profiles past the visible area (now properly scrollable)." },
        { emoji: "🛠️", time: "10:20", title: "A real Admin panel + password reset, for dev profiles", desc: "Dev profiles (the 🛠️ checkbox at profile creation) now get a 🛠️ Admin button in the top bar, listing every registered profile on this hub — name, dev badge, last updated. No passwords are ever shown or stored anywhere in plaintext, not even to admins — the server only ever stores a one-way hash, same as before. What admins CAN do is set a brand-new password for any profile (a real reset), which is enough to actually get someone back into a locked-out account without ever needing to know their old password." },
        { emoji: "🚤", time: "09:10", title: "New game: Coast Guard: Storm Rescue (69 games now!)", desc: "A first/third-person 3D boat game. WASD/arrows to drive (real boat handling — turning needs speed), out on open water rendered in full pseudo-3D perspective, complete with a rolling storm. Find stranded survivors floating in the water, drive up to pick them up (carry a few at once), then race them back to the dock to bank the save before the storm gets bad enough that visibility, waves, and lightning start working against you — and survivors you don't reach in time go under. Dodge floating debris along the way, it damages your hull. Touch controls included. Find it under Action." },
      ],
    },
    {
      date: "2026-07-20",
      entries: [
        { emoji: "📱", time: "23:55", title: "Gun Game Arena: touch controls + Fullscreen", desc: "Mouse-look (Pointer Lock) never worked on iPads/phones — those browsers don't support it at all, so there was simply no way to look around from touch. Added a proper touch scheme: drag the left half of the screen as a virtual joystick to move, drag the right half to look, tap the 🔥 FIRE button to shoot — and it only shows up on touch devices, desktop is untouched. Also added a Fullscreen button." },
        { emoji: "👤", time: "23:45", title: "Kart Circuit & Gun Game Arena: your profile name fills itself in", desc: "Sign in with a profile (👤 Profile button) and both games' multiplayer name fields now prefill with it automatically — no more retyping your name every time you host or join a room. Also fixed: Kart Circuit's chat 🛠️ Dev badge was silently broken (checking a localStorage key the profile system never actually wrote to), so it never showed up even for real dev profiles — it now reads the right place and works." },
        { emoji: "🔫", time: "23:15", title: "Gun Game Arena is now first-person 3D, with online team lobbies", desc: "A full rebuild. It's a real first-person raycaster now (like classic Wolfenstein/DOOM) instead of top-down — walls, obstacles, and rivals all rendered in perspective, mouse-look (click the arena to lock the cursor) or arrow-key turning, gamepad support (left stick move, right stick look, RT/A to fire). New lobby: play solo against bots, or host/join a room with friends over your network (built on the same relay Kart Circuit uses) — set Red and Blue team sizes independently from 1 to 10 each, so anything from 1v1 up to 10v10, or lopsided fights like 1v3, is fair game. Empty slots on either team fill in with bots. Same weapon-ladder core: every kill upgrades you, Knife kill wins it for your team." },
        { emoji: "📍", time: "22:00", title: "Kart Circuit: Dev Mode shows your position", desc: "The Dev Mode overlay now lists your live world coordinates (Pos: x, y) alongside map, checkpoint, lap, and bot count." },
        { emoji: "🛸", time: "21:40", title: "Kart Circuit: moving hazards on every World Tour map", desc: "Each of the 6 World Tour tracks (Rainbow Skyway, Great Savanna, Volcano Rim, Frost Fjord, Cloud Canyon, Turbo City) now has two roaming hazard drones sweeping back and forth across the road on their own clock — clip one and you spin out, just like oil. They show up on the 3D track, the mini-map, and the full map, all from the same live position, so what you see is always what can actually hit you." },
        { emoji: "🩹", time: "21:15", title: "Kart Circuit: fixed a giant white box appearing on the road", desc: "A close-up ramp on a curve could occasionally paint a huge solid-white block across the screen right where the ramp's edge highlight should be — a side effect of last update's fix for pads/ramps/loops going invisible up close: making them stay visible at close range also let their glow lines size up without a limit, and at a steep enough angle that line grew to a few hundred pixels wide. Capped it back down to a normal glowing edge." },
        { emoji: "🦕", time: "18:20", title: "Kart Circuit: a whole shelf of Yoshis", desc: "Mario Kart World style — Yoshi now comes in 9 colors in the Driver picker: green (classic), red, blue, yellow, light-blue, orange, pink, black, and white. Pick one and it rides your kart and shows up recolored in the driver select screen too." },
        { emoji: "🎮", time: "17:10", title: "4 brand new full games: Word Guess, Asteroids, Backgammon, Pinball", desc: "🟩 Word Guess — a Wordle-style 5-letter word guesser with color feedback and an on-screen keyboard. ☄️ Asteroids — rotate, thrust, and blast drifting rocks that split as you shoot them, with a Kart-Circuit-style settings panel (difficulty, sound, screen shake). 🎲 Backgammon — the full classic against a CPU opponent: bar, hitting blots, bearing off, all of it. 🕹️ Pinball — real flipper physics, bumpers, slingshots, and combo scoring, also with a settings panel (ball speed, sound). 67 games now." },
      ],
    },
    {
      date: "2026-07-18",
      entries: [
        { emoji: "✨", time: "20:10", title: "Kart Circuit: boost pads/ramps/loops were invisible right as you reached them", desc: "The mini-map fix surfaced the real bug: driving up to a boost pad, ramp, or loop on a curve, the glowing decal would vanish right as you approached — same root cause as an earlier road-rendering fix, just never applied here. The trigger still fired underneath (it doesn't depend on the camera), so the boost silently happened with zero visual confirmation, which is exactly what got reported. Fixed the same way the road was: these decals now stay visible instead of disappearing, all the way in." },
        { emoji: "🧭", time: "19:55", title: "Kart Circuit: mini-map was missing all the new track features", desc: "Boost pads, jump/glide ramps, loops, and wall-ride zones only ever showed up in the 3D view — the mini-map had no idea they existed, so it genuinely didn't match what you were driving through. It now marks all four: gold/cyan ramp triangles, cyan boost chevrons, magenta loop rings, and a dashed cyan line along wall-ride zones." },
        { emoji: "🔵", time: "19:35", title: "Kart Circuit: boost pads, loops, and Turbo City", desc: "Glowing cyan boost pads on the road give an instant speed kick when you drive over them — every World map has 3–6 now. Bigger: loop rings send you through a real 360° barrel roll (with airtime and an exit boost) — Rainbow Skyway and Cloud Canyon each got one, and 🌍 Turbo City, a brand new sixth World map and the biggest track yet, has two. Turbo City is a neon dusk skyline packed with everything: boost pads, loops, jump and glide ramps, and wall-ride zones, and joins the World Tour cup (now 6 races)." },
        { emoji: "🪂", time: "19:05", title: "Kart Circuit: ramps, gliding, wall rides, drivers & new items!", desc: "The biggest update yet. World maps now have gold trick ramps (jump for a landing boost) and cyan glide ramps that launch you into a real flight with a hang glider. Glowing wall zones let you ride beyond the road edge and cash the ride in as a boost. A new fifth World map — Cloud Canyon, the biggest track of all, high above the clouds — shows them all off (and joins the World Tour cup). Plus: pick your driver (11 characters including 🦕 Yoshi, 🦖 Rexy and 🐲 Spark) and your kart (4 with real stat differences — Speedster, Zippy, Grip Truck, Cruiser), and three new items: ⭐ Star invincibility, ⚡ Lightning that zaps every rival, and 💰 a coin bag." },
        { emoji: "🧭", time: "18:15", title: "Kart Circuit: the mini-map now turns with you", desc: "The mini-map used to be a fixed overhead view, so what it showed never lined up with what you saw — the 3D road would bend right while the track at your dot ran some other direction on the panel. It's now a rotating radar: you're the arrow pinned at the center always pointing up, the map turns as you steer, and the road ahead of the arrow bends exactly the way the road on screen does. It's also zoomed in closer so upcoming corners, coins, and item boxes are actually readable." },
        { emoji: "🎵", time: "17:50", title: "Kart Circuit: race music!", desc: "Races now have a driving chiptune soundtrack — bass line, melody, kick and hi-hat, all generated live by the same synth that makes the sound effects (no audio files). It speeds up and shifts higher on your final lap, pauses when you pause, and respects the Audio toggle." },
        { emoji: "🏆", time: "17:25", title: "Kart Circuit: World Tour — 4 huge tracks, 24 racers, real scenery", desc: "Two more World-scale tracks join Rainbow Skyway and Great Savanna: Volcano Rim (glowing ember curbs under an ash-red sky) and Frost Fjord (an icy ribbon between snow peaks). All four World maps now run Mario-Kart-World-sized 24-racer grids (classic tracks keep 13), and have trackside scenery — acacia trees and rocks on the savanna, floating glow-stars and rainbow arches on the skyway, pulsing lava rocks on the volcano, ice crystals on the fjord. Plus a new 🌍 World Tour cup that runs all four back-to-back." },
        { emoji: "🌍", time: "16:50", title: "Kart Circuit: two huge World-scale tracks", desc: "Rainbow Skyway (a neon night ride through the clouds) and Great Savanna (a golden sunset plain) — both around 3× the size of every other track, with wider roads, S-bend straights, and 2 laps instead of 4. They're so big the 2D Tactical Map can't usefully frame them, so these two are 3D-only: the Mode button locks to \"3D only\" and explains why if you try to switch." },
        { emoji: "🧭", time: "16:20", title: "Kart Circuit: every view finally shows the SAME track", desc: "Two more mismatches found and fixed. The 2D Tactical Map drew the road as straight lines between corner points — but the karts actually drive a smooth curve that bulges outside those lines, so racers and coins looked like they were driving off-road, and the map's whole shape disagreed with the mini-map. It now draws the real curved road. And the mini-map's road ribbon was drawn at barely half its true width, leaving edge-riding karts and coins floating outside it — it's now true to scale. The 3D view, mini-map, and 2D map are all drawn from the same road now." },
        { emoji: "🗺️", time: "15:55", title: "Kart Circuit: the map didn't match the track", desc: "The 2D Tactical Map's grass background (and the mini-map/2D map's zoom level) were built from a leftover, differently-shaped point set that never quite matched the actual road — tight against the road on one side of a loop, oddly far from it on another, and part of why the 3D view's tight bends could look wrong too. The grass boundary is now traced directly from the real road shape, so the map and every view of the track finally agree with each other." },
        { emoji: "🛣️", time: "15:35", title: "Kart Circuit: fixed a phantom road fork on tight tracks", desc: "On short tracks like Neon Loop, the 3D view could occasionally show the road forking into two paths that didn't match the mini-map at all. Near a sharp bend, part of the road briefly falls outside the camera's view for that frame — the renderer was incorrectly stitching the road back together across that gap instead of just leaving it out, creating a stray strip that looked like a fork. It now correctly skips across the gap instead of bridging it." },
        { emoji: "🕹️", time: "15:05", title: "Better support for flight sticks / HOTAS controllers", desc: "Controllers like a Thrustmaster T.Flight Hotas don't report their buttons in the same order as an Xbox/PlayStation pad (browsers can't normalize them), so the gamepad cursor's click button and Kart Circuit's menu-cursor click were landing on the wrong physical control by default. Both are now remappable — press whichever button your device actually has (the hub's gamepad cursor settings, in Play Together, and Kart Circuit's own gamepad panel). Button labels also show plain numbers instead of made-up Nintendo names for these controllers." },
        { emoji: "🌐", time: "14:50", title: "Profiles now actually work across devices", desc: "Profiles used to be saved only in that one browser's storage, so signing in with the same name & password on a different device just said \"no profile with that name\" — confusing, since it looked like an account system but wasn't one. Profiles are now saved on the hub's server: create or save settings on one device, then sign in with the same name & password from any other device on this network and your settings are right there." },
        { emoji: "👻", time: "14:35", title: "Kart Circuit: gamepad cursor vanished in fullscreen", desc: "Going fullscreen while playing Kart Circuit from the hub made the gamepad cursor disappear entirely — the hub's own cursor lives outside the part of the page that stays visible in fullscreen, and Kart Circuit's own backup cursor was deliberately staying out of its way. The two now hand off correctly: the game's own cursor takes over the moment it goes fullscreen." },
        { emoji: "🖵", time: "14:20", title: "Kart Circuit: fullscreen and the gamepad — a browser limit, not a bug", desc: "Toggling fullscreen with the gamepad cursor used to flip the On/Off label without the screen actually going fullscreen. Turns out every browser blocks fullscreen requests unless they come from a real mouse click, tap, or key press — a gamepad button can never satisfy that, by design. We can't code around it, so instead: pressing Y (or clicking Full with the cursor) now shows a clear message and points a 🖱️ hint at the button so you know to grab a real mouse or press F on a keyboard." },
        { emoji: "🐦", time: "13:40", title: "New game: Flappy Wings (63 games now!)", desc: "A fresh Flappy-Bird-style arcade game — flap through pipe gaps with click/tap, Space, or a gamepad button. Tracks your best score. Find it under Action." },
        { emoji: "🖱️", time: "13:25", title: "Gamepad cursor: hover highlighting, fullscreen, and hold-B-to-exit", desc: "Buttons and links now visibly light up as the gamepad cursor moves over them. The cursor and on-screen keyboard also work correctly in fullscreen now (they used to vanish). And in Kart Circuit, holding B for a moment backs out to the game grid — a quick tap still just brakes." },
        { emoji: "🦘", time: "12:50", title: "Kart Circuit: drift now starts with a hop", desc: "Holding drift while turning now kicks off with a little jump before settling into the power-slide, like a real Mario Kart drift-hop — visual only, doesn't change the timing or turbo charge-up." },
        { emoji: "🔑", time: "12:35", title: "Profiles: sign-in was case-sensitive", desc: "Creating a profile as \"Anthony\" and signing in as \"anthony\" (easy to do — phone keyboards auto-capitalize inconsistently) failed with \"No profile with that name,\" even with the right password. Names are now matched regardless of case." },
        { emoji: "📐", time: "12:20", title: "Kart Circuit: 3D view was stretched, now centered", desc: "On wide windows the game canvas was silently stretching to fill the frame instead of keeping its correct proportions, squashing the whole 3D scene sideways. It's now sized explicitly to stay properly proportioned and centered at any window size." },
        { emoji: "☀️", time: "12:10", title: "HDR was washing out the sky", desc: "HDR's glow effect was treating the whole bright sky as a highlight, blooming it into a flat white sheet that hid the sun, mountains, and horizon. The glow now only picks up real highlights (sun, sparks, headlights) — the sky stays clear on every track, including the brightest ones." },
        { emoji: "🐛", time: "12:00", title: "Sprint Race: fixed a guaranteed-win bug", desc: "Holding Space down (instead of mashing it) exploited the browser's key-repeat to sprint far faster than any CPU racer, guaranteeing 1st every time. Holding the key no longer counts — you actually have to mash it now." },
        { emoji: "👤", time: "11:45", title: "Profiles — back up your settings", desc: "Create a name + password from the new 👤 Profile button to back up your gamepad cursor prefs, gamepad mapping, and Kart Circuit preferences (theme, HDR, difficulty, camera, minimap, auto steer). Sign in on any browser here to restore them. Check \"I'm the developer\" to get a 🛠️ Dev badge next to your name, including in Kart Circuit chat. Local to this browser — not a real account system." },
        { emoji: "🗺️", time: "11:10", title: "Bigger tracks, 8 distinct worlds", desc: "Every track is significantly larger with wider roads, and each now has its own look: Neon Loop's synthwave skyline, Canyon Run's dunes, Summit Spiral's snow-capped peaks, Metro Surge's dusk skyline, Foundry Drift's smokestacks, and ocean horizons for Harbor Bend and Boardwalk Dash." },
        { emoji: "🎥", time: "11:05", title: "3D camera fixed", desc: "Getting hit by a rocket or oil used to send the chase/hood camera spinning wildly along with the crash animation, leaving you staring at grass or sky for a second. The camera now holds a steady view of the road through the whole spin." },
        { emoji: "📷", time: "09:40", title: "Video chat in Kart Circuit", desc: "Turn on your camera in a race room and everyone sees each other in small video tiles — works alongside voice chat. There's also a 🧪 Test Cam & Mic button on the setup screen so you can check your camera and watch the mic level meter move, no room needed." },
        { emoji: "🖱️", time: "09:40", title: "Gamepad mouse — everywhere", desc: "A controller-driven pointer for the whole hub and Kart Circuit's menus: left stick moves, right stick scrolls, LT (or A in the hub) clicks — so you can pick a game, choose a map, and hit Start Race from the couch. In the hub the D-pad also plays keyboard games (snake, 2048, pong…) and B goes back." },
        { emoji: "🏎️", time: "08:30", title: "Kart Circuit: 3D mode overhaul", desc: "The road now stretches to the horizon, you can see your own kart (with drift sparks, boost flames, shield bubble, and fall animation), and the minimap shows the real road shape with coins, hazards, and rockets." },
        { emoji: "🔧", time: "08:10", title: "Lap counting fixed", desc: "Two long-standing bugs meant laps often failed to count — the finish gate was narrower than the road, and the lap check ran at the wrong checkpoint. Both fixed; lap farming is still impossible." },
      ],
    },
    {
      date: "2026-07-17",
      entries: [
        { emoji: "🎮", title: "Kart Circuit: real gamepad support (Switch 2 layout)", desc: "One controller per player in split-screen, analog stick steering, and Mario-Kart-style buttons: A accelerate, B brake, ZR drift, ZL item, X camera, + pause. Every button is remappable from the setup screen and your layout is remembered." },
        { emoji: "🏁", title: "Kart Circuit: drift, coins & items", desc: "Hold Shift while turning to drift and release for a mini-turbo. Grab coins for top speed (dropped when you fall!), and item boxes now hold Rockets, Shields, Oil Slicks, and Turbos — AI racers use them too. Plus HDR rendering (now in 2D mode too), proper 3D kart sprites, and coins/items/rockets all visible on the 2D tactical map." },
        { emoji: "📡", title: "Play Together — wireless multiplayer for all 62 games", desc: "Host a room from the new Play Together button, share the 4-letter code, and friends on your network play the same game live from their own computer — their clicks and keys control the shared board." },
        { emoji: "🎉", title: "Local Party — same-PC multiplayer for all 62 games", desc: "2-4 players take turns on one keyboard in any game while the hub keeps score across rounds. Find it inside the Play Together panel." },
        { emoji: "🎮", title: "Local split-screen multiplayer", desc: "Kart Circuit now supports up to 4 players racing together on one PC, one keyboard — 2/3/4-way split-screen with independent cameras, HUDs, and non-overlapping key groups (Arrows, WASD, IJKL, Numpad)." },
        { emoji: "🕳️", title: "Fall off the track", desc: "Drive off the road too long and you'll fall, then respawn at your last checkpoint instead of the start." },
        { emoji: "🔒", title: "Secure LAN play", desc: "The hub now serves over HTTPS with a LAN-trusted certificate so voice chat works for everyone on the network, not just localhost." },
      ],
    },
    {
      date: "2026-07-16",
      entries: [
        { emoji: "🆕", title: "What's New — this panel", desc: "A running changelog for the hub, right here. Click the 🆕 What's New button anytime to see what's changed; a small red dot lights up on the button whenever there's something you haven't seen yet." },
        { emoji: "📡", title: "Wireless multiplayer", desc: "Host or join a Kart Circuit race with up to 13 racers over your local network using a short room code." },
        { emoji: "💬", title: "Chat & voice", desc: "Text chat with player names, plus optional voice chat (WebRTC) while racing together." },
        { emoji: "▶", title: "Animated How to Play guides", desc: "Every one of the 62 games now has a quick animated guide — click \"How to Play\" from any game." },
        { emoji: "✨", title: "Hover animations everywhere", desc: "Buttons, tiles, and cards across the whole hub now respond to hover for a snappier feel." },
        { emoji: "🏁", title: "Kart Circuit added", desc: "A full pseudo-3D kart racer joined the hub — wider view, better AI, boost particles, night skybox, and a Grand Prix cup." },
      ],
    },
  ];

  const btn = document.getElementById("updatesBtn");
  const badge = document.getElementById("updatesBadge");
  const overlay = document.getElementById("updatesOverlay");
  const closeBtn = document.getElementById("updatesCloseBtn");
  const listEl = document.getElementById("updatesList");
  const getUpdatesBtn = document.getElementById("getUpdatesBtn");

  function latestDate() {
    return CHANGELOG[0]?.date || "";
  }

  function syncBadge() {
    const seen = localStorage.getItem(STORAGE_KEY) || "";
    badge.classList.toggle("hidden", seen >= latestDate());
  }

  function render() {
    listEl.innerHTML = CHANGELOG.map((group) => `
      <div>
        <p class="updates-date">${group.date}</p>
        ${group.entries.map((entry) => `
          <div class="update-entry">
            <span class="update-entry-emoji">${entry.emoji}</span>
            <div>
              <p class="update-entry-title">${entry.title}${entry.time ? `<span class="update-entry-time">🕐 ${entry.time}</span>` : ""}</p>
              <p class="update-entry-desc">${entry.desc}</p>
            </div>
          </div>
        `).join("")}
      </div>
    `).join("");
  }

  function isOpen() {
    return !overlay.classList.contains("hidden");
  }

  function open() {
    render();
    overlay.classList.remove("hidden");
    localStorage.setItem(STORAGE_KEY, latestDate());
    syncBadge();
  }

  function close() {
    overlay.classList.add("hidden");
  }

  btn.addEventListener("click", () => (isOpen() ? close() : open()));
  closeBtn.addEventListener("click", close);
  // this is a static site — the freshest build is whatever the server has
  // right now, so "getting updates" just means reloading to pick it up
  getUpdatesBtn.addEventListener("click", () => location.reload());
  overlay.addEventListener("click", (e) => {
    if (e.target === overlay) close();
  });

  syncBadge();

  window.MimiUpdateCenter = { open, close, isOpen };
})();
